                <div className="w-16 h-16 bg-[#F1F3E0] rounded-full flex items-center justify-center mx-auto mb-4 text-[#778873]">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path></svg>
                </div>
                <h4 className="text-lg font-bold text-[#3d382a]">No sessions recorded</h4>
