import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline';
  fullWidth?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  icon,
  className = '',
  ...props 
}) => {
  const baseStyles = "flex items-center justify-center gap-2 px-6 py-3 rounded-2xl font-bold transition-all duration-200 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-[#778873] text-white hover:bg-[#667562] shadow-lg shadow-[#778873]/20",
    secondary: "bg-[#D2DCB6] text-[#3d382a] hover:bg-[#c2cca8]",
    outline: "border-2 border-[#778873] text-[#778873] hover:bg-[#778873]/5"
  };

  const widthClass = fullWidth ? "w-full" : "";

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${widthClass} ${className}`} 
      {...props}
    >
      {icon && <span className="w-5 h-5">{icon}</span>}
      {children}
    </button>
  );
};

export interface Session {
  id: string;
  userId: string;
  timestamp: Date;
  durationSeconds: number;
  exercises: string[];
  painLevel: number; // 1-10
  accuracyScore: number; // Percentage
  aiSummary: string; // Generated by Gemini
}

export enum ViewState {
  DASHBOARD = 'DASHBOARD',
  SESSION = 'SESSION',
}

// MediaPipe Global Types
declare global {
  interface Window {
    Pose: any;
    Camera: any;
    drawConnectors: any;
    drawLandmarks: any;
    POSE_CONNECTIONS: any;
  }
}

import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [repCount, setRepCount] = useState(0);
  const [kneeAngle, setKneeAngle] = useState<number>(180);
  const [isValgus, setIsValgus] = useState(false);
  const [showToast, setShowToast] = useState(false);

  // Deep Analysis State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs (Mutable state that doesn't trigger re-renders for loop)
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);

  // Rep Counting State Machine
  // State: 'UP' | 'DOWN'
  const squatStateRef = useRef<'UP' | 'DOWN'>('UP');

  // Stats for Report
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });

  const calculateAngle = (a: any, b: any, c: any) => {
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);

    if (angle > 180.0) {
      angle = 360 - angle;
    }
    return Math.round(angle);
  };

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      if (results.poseLandmarks) {
        const landmarks = results.poseLandmarks;

        // Landmarks: 23(L_Hip), 24(R_Hip), 25(L_Knee), 26(R_Knee), 27(L_Ankle), 28(R_Ankle)
        const leftHip = landmarks[23];
        const rightHip = landmarks[24];
        const leftKnee = landmarks[25];
        const rightKnee = landmarks[26];
        const leftAnkle = landmarks[27];

        // Visibility Check
        const isVisible = leftHip.visibility > 0.65 && rightHip.visibility > 0.65 && 
                          leftKnee.visibility > 0.65 && rightKnee.visibility > 0.65;

        if (isVisible) {
          statsRef.current.totalFrames++;

          // --- 1. SQUAT DEPTH (Angle) ---
          // Use Left Side for Angle Calculation
          const currentAngle = calculateAngle(leftHip, leftKnee, leftAnkle);
          setKneeAngle(currentAngle);

          // Rep Logic: Standing (>160) <-> Squat (<120)
          if (squatStateRef.current === 'UP' && currentAngle < 120) {
            squatStateRef.current = 'DOWN';
          } else if (squatStateRef.current === 'DOWN' && currentAngle > 160) {
            squatStateRef.current = 'UP';
            setRepCount(prev => prev + 1);
          }

          // --- 2. COACHING LOGIC (Valgus) ---
          // "Caving In" detection using horizontal separation ratios
          const hipSeparation = Math.abs(leftHip.x - rightHip.x);
          const kneeSeparation = Math.abs(leftKnee.x - rightKnee.x);

          // If knees are significantly narrower than hips (approx < 75% width), flag as Valgus
          const valgusDetected = kneeSeparation < (hipSeparation * 0.75);

          if (valgusDetected) {
             setIsValgus(true);
             setShowToast(true);
          } else {
             setIsValgus(false);
             setShowToast(false);
             statsRef.current.goodFrames++;
          }

          // --- 3. DRAWING ---
          // Color Logic: #778873 (Primary Sage) usually, RED (#EF4444) if bad form
          const skeletonColor = valgusDetected ? '#EF4444' : '#778873';
          const landmarkColor = valgusDetected ? '#EF4444' : '#D2DCB6';

          window.drawConnectors(canvasCtx, results.poseLandmarks, window.POSE_CONNECTIONS,
            { color: skeletonColor, lineWidth: 4 });

          window.drawLandmarks(canvasCtx, results.poseLandmarks,
            { color: landmarkColor, lineWidth: 2, radius: 4 });

        } else {
           // Not fully visible, neutral state
           setIsValgus(false);
           setShowToast(false);
        }
      }
      canvasCtx.restore();
    };

    if (window.Pose) {
      pose = new window.Pose({
        locateFile: (file: string) => {
          return `https://cdn.jsdelivr.net/npm/@mediapipe/pose/${file}`;
        }
      });

      pose.setOptions({
        modelComplexity: 1,
        smoothLandmarks: true,
        enableSegmentation: false,
        minDetectionConfidence: 0.5,
        minTrackingConfidence: 0.5
      });

      pose.onResults(onResults);
    }

    const detect = async () => {
      if (
        webcamRef.current && 
        webcamRef.current.video && 
        webcamRef.current.video.readyState === 4 &&
        pose
      ) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    detect();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, []);

  const handleDeepAnalysis = async () => {
    if (!webcamRef.current) return;
    setIsAnalyzing(true);
    setCoachInsight(null);

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            console.error("Failed to capture screenshot");
            setCoachInsight("Camera unavailable. Check permissions.");
            setIsAnalyzing(false);
            return;
        }

        const base64Data = imageSrc.split(',')[1];

        if (!process.env.API_KEY) {
             console.warn("No API Key");
             await new Promise(resolve => setTimeout(resolve, 1500)); // Mock delay
             setCoachInsight("Demo Mode: API Key missing. Ensure your hips remain square to the camera and keep your chest up.");
             setIsAnalyzing(false);
             return;
        }

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    {
                        inlineData: {
                            mimeType: 'image/jpeg',
                            data: base64Data
                        }
                    },
                    {
                        text: "You are a biomechanics expert. Analyze this user's posture in the image. Identify one specific error in their alignment. Be concise (max 25 words)."
                    }
                ]
            }
        });

        const text = response.text;
        setCoachInsight(text || "Analysis result unavailable.");

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    onSave({
        durationSeconds,
        exercises: ['Squats'],
        painLevel: 2,
        accuracyScore: accuracy,
        reps: repCount
    });
  };

  return (
    <div className="fixed inset-0 bg-[#F1F3E0] z-50 flex flex-col">
      {/* Header Overlay */}
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-start z-20 pointer-events-none">
        <div className="bg-[#F1F3E0]/90 backdrop-blur rounded-2xl p-4 shadow-lg pointer-events-auto border border-[#778873]/10">
           <p className="text-xs text-[#726951] font-bold uppercase tracking-wider">Squat Session</p>
           <div className="flex items-baseline gap-1">
             <span className="text-4xl font-bold text-[#778873]">{repCount}</span>
             <span className="text-sm text-[#3d382a] font-medium">Reps</span>
           </div>
        </div>

        <div className="flex gap-2 pointer-events-auto">
            <Button
                variant="secondary"
                onClick={handleDeepAnalysis}
                disabled={isAnalyzing}
                className="!py-2 !px-4 shadow-lg border border-[#778873]/10"
                icon={
                    isAnalyzing ? (
                        <div className="w-4 h-4 border-2 border-[#778873] border-t-transparent rounded-full animate-spin" />
                    ) : (
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z"></path></svg>
                    )
                }
            >
                {isAnalyzing ? "Analyzing..." : "Analyze Form"}
            </Button>
            <Button 
                variant="primary" 
                onClick={handleFinish}
                className="!py-2 !px-4 shadow-xl"
            >
                Finish
            </Button>
            <button 
                onClick={onExit}
                className="bg-white/50 backdrop-blur hover:bg-white/80 text-[#778873] rounded-full p-3 transition-colors border border-[#778873]/10"
            >
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
            </button>
        </div>
      </div>

      {/* Main Vision Area */}
      <div className="relative flex-1 flex items-center justify-center bg-[#D2DCB6]/30 overflow-hidden">
        <Webcam
            ref={webcamRef}
            audio={false}
            screenshotFormat="image/jpeg"
            className="absolute inset-0 w-full h-full object-cover"
            videoConstraints={{ facingMode: "user" }}
        />
        <canvas 
            ref={canvasRef} 
            className="absolute inset-0 w-full h-full object-cover"
        />

        {/* Large Angle Display */}
        <div className="absolute top-1/2 left-8 transform -translate-y-1/2 z-10 pointer-events-none">
            <div className={`
                backdrop-blur-sm p-6 rounded-3xl border shadow-sm transition-all duration-300
                ${isValgus ? 'bg-red-100/95 border-red-200' : 'bg-white/80 border-[#778873]/10'}
            `}>
                <span className={`text-sm font-bold uppercase block mb-1 flex items-center gap-2 ${isValgus ? 'text-red-700' : 'text-[#726951]'}`}>
                   Knee Angle
                </span>
