            <Button 
                onClick={onClose}
                variant="outline"
                fullWidth
            >
                Close & Save
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Dashboard } from './components/Dashboard';
import { SessionView } from './components/SessionView';
import { Header } from './components/Header';
import { ReportCard } from './components/ReportCard';
import { Session, ViewState } from './types';
import { GoogleGenAI } from "@google/genai";

function App() {
  const [view, setView] = useState<ViewState>(ViewState.DASHBOARD);
  // Local state for sessions instead of Firestore
  const [sessions, setSessions] = useState<Session[]>([]);
  // Temp state for report view
  const [currentSession, setCurrentSession] = useState<Session | null>(null);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);

  const handleStartSession = () => {
    setView(ViewState.SESSION);
  };

  const handleBackToDashboard = () => {
    setView(ViewState.DASHBOARD);
  }

  const handleSessionComplete = async (data: any) => {
    setIsGeneratingReport(true);
    // AI Summary Generation
    let summary = "Session analysis unavailable.";

    try {
        if (process.env.API_KEY) {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            // New Specific Clinical Prompt
            const prompt = `Act as a Physiotherapist. Analyze this patient data: 
            Total Reps: ${data.reps}
            Average Knee Angle: ${data.averageAngle} degrees
            Duration: ${data.durationSeconds} seconds
            Form Accuracy: ${data.accuracyScore}%

            Write a 3-sentence clinical observation for their doctor, focusing on stability and consistency.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: prompt,
            });
            if (response.text) {
              summary = response.text;
            }
        } else {
            console.warn("API_KEY not found in env, skipping AI summary.");
            summary = "Great job! Stats recorded locally. Add an API Key for clinical insights.";
        }
    } catch (e) {
        console.error("AI Generation failed", e);
        summary = "Session completed. Unable to generate clinical observation at this time.";
    }

    const newSession: Session = {
        id: Date.now().toString(),
        userId: 'local-user',
        timestamp: new Date(),
        durationSeconds: data.durationSeconds,
        exercises: data.exercises,
        painLevel: data.painLevel,
        accuracyScore: data.accuracyScore,
        reps: data.reps,
        averageAngle: data.averageAngle,
        aiSummary: summary
    };

    setCurrentSession(newSession);
    setView(ViewState.REPORT);
    setIsGeneratingReport(false);
  }

  const handleReportClose = () => {
    if (currentSession) {
        setSessions(prev => [currentSession, ...prev]);
        setCurrentSession(null);
    }
    setView(ViewState.DASHBOARD);
  };

  return (
    <div className="min-h-screen bg-[#F1F3E0] font-sans selection:bg-[#778873] selection:text-white text-[#3d382a]">
      {view === ViewState.DASHBOARD && (
        <Header />
      )}

      <main>
        {view === ViewState.DASHBOARD && (
          <Dashboard sessions={sessions} onStartSession={handleStartSession} />
        )}

        {view === ViewState.SESSION && (
            <>
            {isGeneratingReport ? (
                <div className="fixed inset-0 bg-[#F1F3E0] flex flex-col items-center justify-center z-[60]">
                    <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-[#778873] mb-6"></div>
                    <h2 className="text-2xl font-bold text-[#3d382a] font-display">Generating Clinical Report...</h2>
                    <p className="text-[#726951] mt-2">Dr. AI is analyzing your biomechanics.</p>
                </div>
            ) : (
                <SessionView 
                    onExit={handleBackToDashboard}
                    onSave={handleSessionComplete}
                />
            )}
            </>
        )}

        {view === ViewState.REPORT && currentSession && (
            <ReportCard 
                session={currentSession}
                onClose={handleReportClose}
            />
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [repCount, setRepCount] = useState(0);
  const [kneeAngle, setKneeAngle] = useState<number>(180);
  const [isValgus, setIsValgus] = useState(false);
  const [showToast, setShowToast] = useState(false);

  // Deep Analysis State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs (Mutable state that doesn't trigger re-renders for loop)
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);

  // Stats Accumulators
  const angleSumRef = useRef(0);
  const angleFrameCountRef = useRef(0);

  // Rep Counting State Machine
  // State: 'UP' | 'DOWN'
  const squatStateRef = useRef<'UP' | 'DOWN'>('UP');

  // Stats for Report
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });

  const calculateAngle = (a: any, b: any, c: any) => {
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);

    if (angle > 180.0) {
      angle = 360 - angle;
    }
    return Math.round(angle);
  };

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      if (results.poseLandmarks) {
        const landmarks = results.poseLandmarks;

        // Landmarks: 23(L_Hip), 24(R_Hip), 25(L_Knee), 26(R_Knee), 27(L_Ankle), 28(R_Ankle)
        const leftHip = landmarks[23];
        const rightHip = landmarks[24];
        const leftKnee = landmarks[25];
        const rightKnee = landmarks[26];
        const leftAnkle = landmarks[27];

        // Visibility Check
        const isVisible = leftHip.visibility > 0.65 && rightHip.visibility > 0.65 && 
                          leftKnee.visibility > 0.65 && rightKnee.visibility > 0.65;

        if (isVisible) {
          statsRef.current.totalFrames++;

          // --- 1. SQUAT DEPTH (Angle) ---
          // Use Left Side for Angle Calculation
          const currentAngle = calculateAngle(leftHip, leftKnee, leftAnkle);
          setKneeAngle(currentAngle);

          // Accumulate for Average
          angleSumRef.current += currentAngle;
          angleFrameCountRef.current += 1;

          // Rep Logic: Standing (>160) <-> Squat (<120)
          if (squatStateRef.current === 'UP' && currentAngle < 120) {
            squatStateRef.current = 'DOWN';
          } else if (squatStateRef.current === 'DOWN' && currentAngle > 160) {
            squatStateRef.current = 'UP';
            setRepCount(prev => prev + 1);
          }

          // --- 2. COACHING LOGIC (Valgus) ---
          // "Caving In" detection using horizontal separation ratios
          const hipSeparation = Math.abs(leftHip.x - rightHip.x);
          const kneeSeparation = Math.abs(leftKnee.x - rightKnee.x);

          // If knees are significantly narrower than hips (approx < 75% width), flag as Valgus
          const valgusDetected = kneeSeparation < (hipSeparation * 0.75);

          if (valgusDetected) {
             setIsValgus(true);
             setShowToast(true);
          } else {
             setIsValgus(false);
             setShowToast(false);
             statsRef.current.goodFrames++;
          }

          // --- 3. DRAWING ---
          // Color Logic: #778873 (Primary Sage) usually, RED (#EF4444) if bad form
          const skeletonColor = valgusDetected ? '#EF4444' : '#778873';
          const landmarkColor = valgusDetected ? '#EF4444' : '#D2DCB6';

          window.drawConnectors(canvasCtx, results.poseLandmarks, window.POSE_CONNECTIONS,
            { color: skeletonColor, lineWidth: 4 });

          window.drawLandmarks(canvasCtx, results.poseLandmarks,
            { color: landmarkColor, lineWidth: 2, radius: 4 });

        } else {
           // Not fully visible, neutral state
           setIsValgus(false);
           setShowToast(false);
        }
      }
      canvasCtx.restore();
    };

    if (window.Pose) {
      pose = new window.Pose({
        locateFile: (file: string) => {
          return `https://cdn.jsdelivr.net/npm/@mediapipe/pose/${file}`;
        }
      });

      pose.setOptions({
        modelComplexity: 1,
        smoothLandmarks: true,
        enableSegmentation: false,
        minDetectionConfidence: 0.5,
        minTrackingConfidence: 0.5
      });

      pose.onResults(onResults);
    }

    const detect = async () => {
      if (
        webcamRef.current && 
        webcamRef.current.video && 
        webcamRef.current.video.readyState === 4 &&
        pose
      ) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    detect();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, []);

  const handleDeepAnalysis = async () => {
    if (!webcamRef.current) return;
    setIsAnalyzing(true);
    setCoachInsight(null);

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            console.error("Failed to capture screenshot");
            setCoachInsight("Camera unavailable. Check permissions.");
            setIsAnalyzing(false);
            return;
        }

        const base64Data = imageSrc.split(',')[1];

        if (!process.env.API_KEY) {
             console.warn("No API Key");
             await new Promise(resolve => setTimeout(resolve, 1500)); // Mock delay
             setCoachInsight("Demo Mode: Shoulders appear level. Keep spine neutral and chin tucked.");
             setIsAnalyzing(false);
             return;
        }

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    {
                        inlineData: {
                            mimeType: 'image/jpeg',
                            data: base64Data
                        }
                    },
                    {
                        text: "Look at the user's posture. Are their shoulders level? Is their spine neutral? Give one specific correction."
                    }
                ]
            }
        });

        const text = response.text;
        setCoachInsight(text || "Analysis result unavailable.");

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    const averageAngle = angleFrameCountRef.current > 0 
        ? Math.round(angleSumRef.current / angleFrameCountRef.current) 
        : 180;

    onSave({
        durationSeconds,
        exercises: ['Squats'],
        painLevel: 2, // Default/Mock for now
        accuracyScore: accuracy,
        reps: repCount,
        averageAngle: averageAngle
    });
  };

  return (
    <div className="fixed inset-0 bg-[#F1F3E0] z-50 flex flex-col">
      {/* Header Overlay */}
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-start z-20 pointer-events-none">
        <div className="bg-[#F1F3E0]/90 backdrop-blur rounded-2xl p-4 shadow-lg pointer-events-auto border border-[#778873]/10">
           <p className="text-xs text-[#726951] font-bold uppercase tracking-wider">Squat Session</p>
           <div className="flex items-baseline gap-1">
             <span className="text-4xl font-bold text-[#778873]">{repCount}</span>
             <span className="text-sm text-[#3d382a] font-medium">Reps</span>
           </div>
        </div>

        <div className="flex gap-2 pointer-events-auto">
            <Button
                variant="secondary"
                onClick={handleDeepAnalysis}
                disabled={isAnalyzing}
                className="!py-2 !px-4 shadow-lg border border-[#778873]/10"
                icon={
                    isAnalyzing ? (
                        <div className="w-4 h-4 border-2 border-[#778873] border-t-transparent rounded-full animate-spin" />
                    ) : (
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                    )
                }
            >
                {isAnalyzing ? "Analyzing..." : "Analyze Posture"}
            </Button>
            <Button 
                variant="primary" 
                onClick={handleFinish}
                className="!py-2 !px-4 shadow-xl"
            >
                End Session
            </Button>
            <button 
                onClick={onExit}
                className="bg-white/50 backdrop-blur hover:bg-white/80 text-[#778873] rounded-full p-3 transition-colors border border-[#778873]/10"
            >
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
            </button>
        </div>
      </div>

      {/* Main Vision Area */}
      <div className="relative flex-1 flex items-center justify-center bg-[#D2DCB6]/30 overflow-hidden">
        <Webcam
            ref={webcamRef}
            audio={false}
            screenshotFormat="image/jpeg"
            className="absolute inset-0 w-full h-full object-cover"
            videoConstraints={{ facingMode: "user" }}
        />
        <canvas 
            ref={canvasRef} 
            className="absolute inset-0 w-full h-full object-cover"
        />

        {/* Large Angle Display */}
        <div className="absolute top-1/2 left-8 transform -translate-y-1/2 z-10 pointer-events-none">
            <div className={`
                backdrop-blur-sm p-6 rounded-3xl border shadow-sm transition-all duration-300
                ${isValgus ? 'bg-red-100/95 border-red-200' : 'bg-white/80 border-[#778873]/10'}
            `}>
                <span className={`text-sm font-bold uppercase block mb-1 flex items-center gap-2 ${isValgus ? 'text-red-700' : 'text-[#726951]'}`}>
                   Knee Angle
                </span>
                <div className="flex items-center gap-3">
                    <svg className={`w-8 h-8 ${isValgus ? 'text-red-600' : 'text-[#778873]'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 14l-7 7m0 0l-7-7m7 7V3" transform="rotate(45, 12, 12)" />
                    </svg>
                    <span className={`text-6xl font-bold tracking-tighter transition-colors duration-300 ${isValgus ? 'text-[#EF4444]' : 'text-[#3d382a]'}`}>
                        {kneeAngle}°
                    </span>
                </div>

                <div className="mt-2 h-1 w-full bg-gray-200 rounded-full overflow-hidden">
                    <div 
                        className={`h-full transition-all duration-300 ${isValgus ? 'bg-[#EF4444]' : 'bg-[#778873]'}`} 
                        style={{ width: `${Math.min(100, (kneeAngle / 180) * 100)}%` }}
                    />
                </div>
            </div>
        </div>

        {/* Coach's Insight Toast (Deep Analysis Result) */}
        {coachInsight && (
           <div className="absolute top-24 left-0 right-0 flex justify-center z-50 pointer-events-none">
             <div className="bg-[#F1F3E0]/95 backdrop-blur-md p-4 rounded-2xl shadow-xl border border-[#A1BC98] pointer-events-auto max-w-md flex items-start gap-4 animate-fade-in-down">
                <div className="p-2 bg-[#778873] rounded-full text-white shrink-0">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                </div>
                <div className="flex-1">
                    <p className="text-[#778873] font-bold text-xs uppercase tracking-wider mb-1">AI Posture Analysis</p>
                    <p className="text-[#3d382a] text-sm leading-relaxed">
                        {coachInsight}
                    </p>
                </div>
                 <button 
                    onClick={() => setCoachInsight(null)}
                    className="text-[#726951] hover:text-[#778873]"
                 >
                     <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                 </button>
             </div>
           </div>
        )}

        {/* Real-time Valgus Toast - Centered Top/Middle */}
        {showToast && (
          <div className="absolute top-44 left-0 right-0 flex justify-center z-30 pointer-events-none animate-bounce">
             <div className="bg-[#EF4444] text-white px-6 py-3 rounded-xl shadow-xl flex items-center gap-3">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                <span className="font-bold">Your knee is rotating inward; try engaging your glute.</span>
             </div>
          </div>
        )}

        {/* Loading State */}
        {!window.Pose && (
             <div className="absolute inset-0 flex items-center justify-center bg-[#F1F3E0] z-30">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#778873] mx-auto mb-4"></div>
                    <p className="text-[#3d382a] font-medium">Initializing Vision Engine...</p>
                </div>
             </div>
        )}
      </div>

      {/* Bottom Status Bar */}
      <div className="absolute bottom-10 left-0 right-0 flex justify-center z-20 pointer-events-none">
          <div className={`
            px-8 py-4 rounded-2xl backdrop-blur-md shadow-xl transition-all duration-300 transform border
            ${isValgus 
                ? 'bg-red-50 border-red-200 text-red-800' 
                : 'bg-white/90 border-[#778873]/10 text-[#778873]'}
          `}>
            <p className="text-lg font-bold flex items-center gap-2">
                {isValgus ? (
                     <>Fix Form</>
                ) : (
                    <>
                        <svg className="w-5 h-5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                        Good Form
                    </>
                )}
            </p>
          </div>
      </div>
    </div>
  );
};

