import React, { useState } from 'react';
import { Dashboard } from './components/Dashboard';
import { SessionView } from './components/SessionView';
import { Header } from './components/Header';
import { ReportCard } from './components/ReportCard';
import { Session, ViewState } from './types';
import { GoogleGenAI } from "@google/genai";

function App() {
  const [view, setView] = useState<ViewState>(ViewState.DASHBOARD);
  // Local state for sessions instead of Firestore
  const [sessions, setSessions] = useState<Session[]>([]);
  // Temp state for report view
  const [currentSession, setCurrentSession] = useState<Session | null>(null);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);

  const handleStartSession = () => {
    setView(ViewState.SESSION);
  };

  const handleBackToDashboard = () => {
    setView(ViewState.DASHBOARD);
  }

  const handleSessionComplete = async (data: any) => {
    setIsGeneratingReport(true);
    let summary = "Session analysis unavailable.";

    try {
        const storedKey = localStorage.getItem('kinexa_api_key');

        if (storedKey) {
            // Real AI Call
            const ai = new GoogleGenAI({ apiKey: storedKey });
            const prompt = `Act as a Physiotherapist. Analyze this patient data: 
            Total Reps: ${data.reps}
            Average Knee Angle: ${data.averageAngle} degrees
            Duration: ${data.durationSeconds} seconds
            Form Accuracy: ${data.accuracyScore}%

            Write a 3-sentence clinical observation for their doctor, focusing on stability and consistency.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: prompt,
            });
            if (response.text) {
              summary = response.text;
            }
        } else {
            // Simulated Demo Response
            console.log("Demo Mode: Simulating AI response");
            await new Promise(resolve => setTimeout(resolve, 2000)); // 2s delay for realism
            summary = "DEMO ANALYSIS: Patient demonstrates consistent rhythm. Knee alignment is stable with no signs of valgus collapse. Maintain core engagement to improve balance in later reps. (Enter API Key in Settings for live AI).";
        }
    } catch (e) {
        console.error("AI Generation failed", e);
        summary = "Session completed. Unable to generate clinical observation at this time.";
    }

    const newSession: Session = {
        id: Date.now().toString(),
        userId: 'local-user',
        timestamp: new Date(),
        durationSeconds: data.durationSeconds,
        exercises: data.exercises,
        painLevel: data.painLevel,
        accuracyScore: data.accuracyScore,
        reps: data.reps,
        averageAngle: data.averageAngle,
        aiSummary: summary
    };

    setCurrentSession(newSession);
    setView(ViewState.REPORT);
    setIsGeneratingReport(false);
  }

  const handleReportClose = () => {
    if (currentSession) {
        setSessions(prev => [currentSession, ...prev]);
        setCurrentSession(null);
    }
    setView(ViewState.DASHBOARD);
  };

  return (
    <div className="min-h-screen bg-white font-sans selection:bg-[#778873] selection:text-white text-gray-900">
      {view === ViewState.DASHBOARD && (
        <Header />
      )}

      <main>
        {view === ViewState.DASHBOARD && (
          <Dashboard sessions={sessions} onStartSession={handleStartSession} />
        )}

        {view === ViewState.SESSION && (
            <>
            {isGeneratingReport ? (
                <div className="fixed inset-0 bg-white/95 flex flex-col items-center justify-center z-[60] backdrop-blur-sm">
                    <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-[#778873] mb-6"></div>
                    <h2 className="text-2xl font-bold text-gray-900 font-display">Generating Clinical Report...</h2>
                    <p className="text-slate-600 mt-2">Dr. AI is analyzing your biomechanics.</p>
                </div>
            ) : (
                <SessionView 
                    onExit={handleBackToDashboard}
                    onSave={handleSessionComplete}
                />
            )}
            </>
        )}

        {view === ViewState.REPORT && currentSession && (
            <ReportCard 
                session={currentSession}
                onClose={handleReportClose}
            />
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

const EXERCISE_OPTIONS = [
  'Squats',
  'Pushups',
  'Burpees',
  'Lunges',
  'Triceps Dip',
  'Plank',
  'Mountain Climber',
  'Stretches'
];

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [currentExercise, setCurrentExercise] = useState('Squats');
  const [repCount, setRepCount] = useState(0);
  const [displayMetric, setDisplayMetric] = useState<number>(0); 
  const [metricLabel, setMetricLabel] = useState('Angle');

  // Feedback State
  const [isBadForm, setIsBadForm] = useState(false);
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');

  // Deep Analysis State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);
  const angleSumRef = useRef(0);
  const angleFrameCountRef = useRef(0);
  const squatStateRef = useRef<'UP' | 'DOWN'>('UP');
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });

  // --- Geometry Helpers ---
  const calculateAngle = (a: any, b: any, c: any) => {
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);
    if (angle > 180.0) angle = 360 - angle;
    return Math.round(angle);
  };

  const calculateDistanceX = (a: any, b: any) => Math.abs(a.x - b.x);

  useEffect(() => {
    setRepCount(0);
    statsRef.current = { goodFrames: 0, totalFrames: 0 };
    angleSumRef.current = 0;
    angleFrameCountRef.current = 0;
  }, [currentExercise]);

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      if (results.poseLandmarks) {
        const lm = results.poseLandmarks;
        const leftEar = lm[7];
        const rightEar = lm[8];
        const leftShoulder = lm[11];
        const rightShoulder = lm[12];
        const leftHip = lm[23];
        const rightHip = lm[24];
        const leftKnee = lm[25];
        const rightKnee = lm[26];
        const leftAnkle = lm[27];

        statsRef.current.totalFrames++;
        let frameBadForm = false;
        let frameMsg = '';

        // Auto Lateral Detection
        const shoulderWidthX = calculateDistanceX(leftShoulder, rightShoulder);
        const isLateral = shoulderWidthX < 0.15; 

        if (isLateral) {
            setMetricLabel('Lateral');
            setDisplayMetric(Math.round(shoulderWidthX * 100));

            const isLeft = leftShoulder.visibility > rightShoulder.visibility;
            const ear = isLeft ? leftEar : rightEar;
            const shoulder = isLeft ? leftShoulder : rightShoulder;
            const hip = isLeft ? leftHip : rightHip;

            const headOffset = Math.abs(ear.x - shoulder.x);

            if (headOffset > 0.08) {
                frameBadForm = true;
                frameMsg = "Head forward posture detected.";
            }

            canvasCtx.beginPath();
            canvasCtx.moveTo(ear.x * videoWidth, ear.y * videoHeight);
            canvasCtx.lineTo(hip.x * videoWidth, hip.y * videoHeight);
            canvasCtx.strokeStyle = frameBadForm ? '#EF4444' : '#778873';
            canvasCtx.lineWidth = 3;
            canvasCtx.setLineDash([5, 5]);
            canvasCtx.stroke();
            canvasCtx.setLineDash([]);

        } else {
            switch(currentExercise) {
                case 'Squats': {
                    setMetricLabel('Knee Angle');
                    const angle = calculateAngle(leftHip, leftKnee, leftAnkle);
                    setDisplayMetric(angle);

                    angleSumRef.current += angle;
                    angleFrameCountRef.current += 1;

                    if (squatStateRef.current === 'UP' && angle < 120) {
                        squatStateRef.current = 'DOWN';
                    } else if (squatStateRef.current === 'DOWN' && angle > 160) {
                        squatStateRef.current = 'UP';
                        setRepCount(p => p + 1);
                    }

                    const hipSep = Math.abs(leftHip.x - rightHip.x);
                    const kneeSep = Math.abs(leftKnee.x - rightKnee.x);
                    if (kneeSep < (hipSep * 0.75)) {
                        frameBadForm = true;
                        frameMsg = "Knee valgus detected.";
                    }
                    break;
                }
                case 'Plank': {
                    setMetricLabel('Hip Level');
                    const shoulderSlope = Math.abs(leftShoulder.y - rightShoulder.y);
                    setDisplayMetric(Math.round(shoulderSlope * 100));

                    if (shoulderSlope > 0.1) {
                        frameBadForm = true;
                        frameMsg = "Keep shoulders level.";
                    }
                    break;
                }
                default:
                    setDisplayMetric(0);
                    setMetricLabel('Tracking');
                    break;
            }
        }

        if (frameBadForm) {
            setIsBadForm(true);
            setFeedbackMessage(frameMsg);
        } else {
            setIsBadForm(false);
            setFeedbackMessage('');
            statsRef.current.goodFrames++;
        }

        // Draw Skeleton using new Brand Colors
        const skeletonColor = frameBadForm ? '#EF4444' : '#778873';
        const landmarkColor = frameBadForm ? '#EF4444' : '#D2DCB6';

        window.drawConnectors(canvasCtx, results.poseLandmarks, window.POSE_CONNECTIONS,
            { color: skeletonColor, lineWidth: 4 });

        window.drawLandmarks(canvasCtx, results.poseLandmarks,
            { color: landmarkColor, lineWidth: 2, radius: 4 });
      }
      canvasCtx.restore();
    };

    const initializePose = async () => {
        if (window.Pose) {
            pose = new window.Pose({
                locateFile: (file: string) => {
                    return `https://cdn.jsdelivr.net/npm/@mediapipe/pose@0.5.1675469404/${file}`;
                }
            });

            pose.setOptions({
                modelComplexity: 1,
                smoothLandmarks: true,
                enableSegmentation: false,
                minDetectionConfidence: 0.5,
                minTrackingConfidence: 0.5
            });

            pose.onResults(onResults);
            if (pose.initialize) await pose.initialize();
            detect();
        }
    };

    const detect = async () => {
      if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4 && pose) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    initializePose();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, [currentExercise]);

  const handleDeepAnalysis = async () => {
    if (!webcamRef.current) return;
    setIsAnalyzing(true);
    setCoachInsight(null);

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            setCoachInsight("Camera unavailable.");
            setIsAnalyzing(false);
            return;
        }

        const storedKey = localStorage.getItem('kinexa_api_key');

        // SMART DEMO MODE
        if (storedKey) {
            const base64Data = imageSrc.split(',')[1];
            const ai = new GoogleGenAI({ apiKey: storedKey });
            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: {
                    parts: [
                        { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
                        { text: `Analyze this ${currentExercise} form. Is the spine neutral? Give one specific correction.` }
                    ]
                }
            });
            setCoachInsight(response.text || "Analysis result unavailable.");
        } else {
            // Simulated Analysis
            await new Promise(resolve => setTimeout(resolve, 1500));
            setCoachInsight("DEMO ANALYSIS: Posture is stable. Shoulders are aligned. Spine is neutral. (Enter API Key in Settings for live AI).");
        }

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    onSave({
        durationSeconds,
        exercises: [currentExercise],
        painLevel: 2, 
        accuracyScore: accuracy,
        reps: repCount,
        averageAngle: Math.round(angleSumRef.current / (angleFrameCountRef.current || 1))
    });
  };

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-[100dvh]">

      {/* 1. Header Bar */}
      <div className="shrink-0 z-20 p-4 flex justify-between items-center bg-white/95 backdrop-blur-sm border-b border-gray-200">
         <div className="flex items-center gap-4 flex-1">
             {/* Exercise Dropdown - Professional Style */}
             <select 
                value={currentExercise}
                onChange={(e) => setCurrentExercise(e.target.value)}
                className="bg-white text-[#778873] border border-gray-300 rounded-xl px-4 py-2 text-sm font-bold uppercase tracking-wider focus:outline-none focus:ring-2 focus:ring-[#778873]/50 focus:border-[#778873] cursor-pointer appearance-none shadow-sm transition-all hover:border-[#778873]"
             >
                {EXERCISE_OPTIONS.map(ex => (
                    <option key={ex} value={ex}>{ex}</option>
                ))}
             </select>

             <div className="w-px h-6 bg-gray-200"></div>

             {/* Rep Counter */}
             <div className="flex items-baseline gap-1">
                 <span className="text-3xl font-bold text-[#778873] tabular-nums">{repCount}</span>
                 <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Reps</span>
             </div>
         </div>
         <button 
            onClick={onExit}
            className="text-slate-400 p-2 bg-gray-50 rounded-full hover:bg-gray-100 hover:text-gray-900 transition-colors"
         >
             <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
         </button>
      </div>

      {/* 2. Main Vision Area */}
      <div className="relative flex-1 bg-gray-50 overflow-hidden flex flex-col justify-center items-center p-4">
         {/* Webcam Container - Rounded & Centered & Responsive */}
         <div className="relative w-full h-full max-w-5xl max-h-full flex items-center justify-center bg-white rounded-3xl shadow-sm border border-gray-200 overflow-hidden aspect-video md:aspect-auto">
             <Webcam
                ref={webcamRef}
                audio={false}
                screenshotFormat="image/jpeg"
                className="absolute w-full h-full object-cover md:object-contain"
