            {Math.floor(session.durationSeconds / 60)}m {session.durationSeconds % 60}s
        </span>
        <span className="flex items-center gap-1.5">
             <span className="w-2 h-2 rounded-full bg-slate-300"></span>
             Pain Level: {session.painLevel}/10
        </span>
      </div>
