import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

const EXERCISE_OPTIONS = [
  'Squats',
  'Pushups',
  'Burpees',
  'Lunges',
  'Triceps Dip',
  'Plank',
  'Mountain Climber',
  'Stretches'
];

type ExercisePhase = 'STANDING' | 'DESCENDING' | 'BOTTOM' | 'ASCENDING' | 'HOLDING' | 'REST';

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [currentExercise, setCurrentExercise] = useState('Squats');
  const [repCount, setRepCount] = useState(0);
  const [displayMetric, setDisplayMetric] = useState<number>(0); 
  const [metricLabel, setMetricLabel] = useState('Angle');
  const [phase, setPhase] = useState<ExercisePhase>('STANDING');
  const [holdTimer, setHoldTimer] = useState(0);

  // Feedback State
  const [isBadForm, setIsBadForm] = useState(false);
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');

  // Deep Analysis State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);
  const angleSumRef = useRef(0);
  const angleFrameCountRef = useRef(0);

  // State Machine Ref (To avoid stale closures in loop)
  const phaseRef = useRef<ExercisePhase>('STANDING');
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });
  const lastHoldTickRef = useRef<number>(0);

  // --- Geometry Helpers ---
  const calculateAngle = (a: any, b: any, c: any) => {
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);
    if (angle > 180.0) angle = 360 - angle;
    return Math.round(angle);
  };

  const calculateDistanceX = (a: any, b: any) => Math.abs(a.x - b.x);

  useEffect(() => {
    // Reset stats on exercise change
    setRepCount(0);
    setHoldTimer(0);
    statsRef.current = { goodFrames: 0, totalFrames: 0 };
    angleSumRef.current = 0;
    angleFrameCountRef.current = 0;
    phaseRef.current = 'STANDING';
    setPhase('STANDING');
  }, [currentExercise]);

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      if (results.poseLandmarks) {
        const lm = results.poseLandmarks;
        const leftEar = lm[7];
        const rightEar = lm[8];
        const leftShoulder = lm[11];
        const rightShoulder = lm[12];
        const leftHip = lm[23];
        const rightHip = lm[24];
        const leftKnee = lm[25];
        const rightKnee = lm[26];
        const leftAnkle = lm[27];
        const rightAnkle = lm[28];

        statsRef.current.totalFrames++;
        let frameBadForm = false;
        let frameMsg = '';

        // Auto Lateral Detection
        const shoulderWidthX = calculateDistanceX(leftShoulder, rightShoulder);
        const isLateral = shoulderWidthX < 0.15; 

        if (isLateral) {
            setMetricLabel('Lateral');
            setDisplayMetric(Math.round(shoulderWidthX * 100));

            const isLeft = leftShoulder.visibility > rightShoulder.visibility;
            const ear = isLeft ? leftEar : rightEar;
            const shoulder = isLeft ? leftShoulder : rightShoulder;
            const hip = isLeft ? leftHip : rightHip;
            const knee = isLeft ? leftKnee : rightKnee;
            const ankle = isLeft ? leftAnkle : rightAnkle;

            // Simple Lateral Squat Logic if Needed
            if (currentExercise === 'Squats') {
                 const angle = calculateAngle(hip, knee, ankle);
                 setDisplayMetric(angle);
            }

            const headOffset = Math.abs(ear.x - shoulder.x);
            if (headOffset > 0.08) {
                frameBadForm = true;
                frameMsg = "Head forward detected.";
            }

            canvasCtx.beginPath();
            canvasCtx.moveTo(ear.x * videoWidth, ear.y * videoHeight);
            canvasCtx.lineTo(hip.x * videoWidth, hip.y * videoHeight);
            canvasCtx.strokeStyle = frameBadForm ? '#EF4444' : '#778873';
            canvasCtx.lineWidth = 3;
            canvasCtx.setLineDash([5, 5]);
            canvasCtx.stroke();
            canvasCtx.setLineDash([]);

        } else {
            switch(currentExercise) {
                case 'Squats': {
                    setMetricLabel('Knee Angle');
                    const angle = calculateAngle(leftHip, leftKnee, leftAnkle);
                    setDisplayMetric(angle);

                    angleSumRef.current += angle;
                    angleFrameCountRef.current += 1;

                    // --- SQUAT STATE MACHINE ---
                    // State A (Standing): > 165
                    // State B (Bottom): < 140
                    const currentPhase = phaseRef.current;
                    let nextPhase = currentPhase;

                    if (currentPhase === 'STANDING') {
                        if (angle < 160) nextPhase = 'DESCENDING';
                    } 
                    else if (currentPhase === 'DESCENDING') {
                        if (angle < 140) nextPhase = 'BOTTOM';
                        else if (angle > 170) nextPhase = 'STANDING'; // Aborted rep
                    }
                    else if (currentPhase === 'BOTTOM') {
                        if (angle > 140) nextPhase = 'ASCENDING';
                    }
                    else if (currentPhase === 'ASCENDING') {
                        if (angle > 165) {
                            nextPhase = 'STANDING';
                            setRepCount(c => c + 1); // SUCCESSFUL REP
                        } else if (angle < 130) {
                            nextPhase = 'BOTTOM'; // Failed to rise, went back down
                        }
                    }

                    if (nextPhase !== currentPhase) {
                        phaseRef.current = nextPhase;
                        setPhase(nextPhase);
                    }

                    const hipSep = Math.abs(leftHip.x - rightHip.x);
                    const kneeSep = Math.abs(leftKnee.x - rightKnee.x);
                    if (kneeSep < (hipSep * 0.75)) {
                        frameBadForm = true;
                        frameMsg = "Knee valgus detected.";
                    }
                    break;
                }
                case 'Plank': {
                    setMetricLabel('Shoulder Level');
                    const shoulderSlope = Math.abs(leftShoulder.y - rightShoulder.y);
                    setDisplayMetric(Math.round(shoulderSlope * 100));

                    // Timer Logic
                    // If slope is good (< 0.15) increment hold timer
                    if (shoulderSlope < 0.15) {
                        const now = Date.now();
                        if (now - lastHoldTickRef.current > 1000) {
                            setHoldTimer(t => t + 1);
                            lastHoldTickRef.current = now;
                        }
                        if (phaseRef.current !== 'HOLDING') {
                            phaseRef.current = 'HOLDING';
                            setPhase('HOLDING');
                        }
                    } else {
                         frameBadForm = true;
                         frameMsg = "Keep shoulders level.";
                         if (phaseRef.current !== 'REST') {
                             phaseRef.current = 'REST';
                             setPhase('REST');
                         }
                    }
                    break;
                }
                default:
                    setDisplayMetric(0);
                    setMetricLabel('Tracking');
                    break;
            }
        }

        if (frameBadForm) {
            setIsBadForm(true);
            setFeedbackMessage(frameMsg);
        } else {
            setIsBadForm(false);
            setFeedbackMessage('');
            statsRef.current.goodFrames++;
        }

        const skeletonColor = frameBadForm ? '#EF4444' : '#778873';
        const landmarkColor = frameBadForm ? '#EF4444' : '#D2DCB6';

        window.drawConnectors(canvasCtx, results.poseLandmarks, window.POSE_CONNECTIONS,
            { color: skeletonColor, lineWidth: 4 });

        window.drawLandmarks(canvasCtx, results.poseLandmarks,
            { color: landmarkColor, lineWidth: 2, radius: 4 });
      }
      canvasCtx.restore();
    };

    const initializePose = async () => {
        if (window.Pose) {
            pose = new window.Pose({
                locateFile: (file: string) => {
                    return `https://cdn.jsdelivr.net/npm/@mediapipe/pose@0.5.1675469404/${file}`;
                }
            });

            pose.setOptions({
                modelComplexity: 1,
                smoothLandmarks: true,
                enableSegmentation: false,
                minDetectionConfidence: 0.5,
                minTrackingConfidence: 0.5
            });

            pose.onResults(onResults);
            if (pose.initialize) await pose.initialize();
            detect();
        }
    };

    const detect = async () => {
      if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4 && pose) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    initializePose();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, [currentExercise]);

  const handleDeepAnalysis = async () => {
    if (!webcamRef.current) return;
    setIsAnalyzing(true);
    setCoachInsight(null);

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            setCoachInsight("Camera unavailable.");
            setIsAnalyzing(false);
            return;
        }

        const base64Data = imageSrc.split(',')[1];
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
                    { text: `Analyze this ${currentExercise} form. Is the spine neutral? Give one specific correction.` }
                ]
            }
        });
        setCoachInsight(response.text || "Analysis result unavailable.");

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    onSave({
        durationSeconds,
        exercises: [currentExercise],
        painLevel: 2, 
        accuracyScore: accuracy,
        reps: currentExercise === 'Plank' ? 0 : repCount, // No reps for plank
        averageAngle: Math.round(angleSumRef.current / (angleFrameCountRef.current || 1))
    });
  };

  // Helper to format seconds to MM:SS
  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-[100dvh]">

      {/* 1. Header Bar */}
      <div className="shrink-0 z-20 p-4 flex justify-between items-center bg-white/95 backdrop-blur-sm border-b border-gray-100">
         <div className="flex items-center gap-4 flex-1">
             {/* Exercise Dropdown - Professional Style */}
             <select 
                value={currentExercise}
                onChange={(e) => setCurrentExercise(e.target.value)}
                className="bg-white text-[#778873] border border-gray-200 rounded-xl px-4 py-2 text-sm font-bold uppercase tracking-wider focus:outline-none focus:ring-2 focus:ring-[#778873]/50 focus:border-[#778873] cursor-pointer appearance-none shadow-sm transition-all hover:border-[#778873]"
             >
                {EXERCISE_OPTIONS.map(ex => (
                    <option key={ex} value={ex}>{ex}</option>
                ))}
             </select>

             <div className="w-px h-6 bg-gray-200"></div>

             {/* Dynamic Metric: Reps or Timer */}
             {currentExercise === 'Plank' ? (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{formatTime(holdTimer)}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Hold Time</span>
                </div>
             ) : (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{repCount}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Reps</span>
                </div>
             )}
         </div>
         <button 
            onClick={onExit}
            className="text-slate-400 p-2 bg-gray-50 rounded-full hover:bg-gray-100 hover:text-gray-900 transition-colors"
         >
             <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
         </button>
      </div>

      {/* 2. Main Vision Area */}
      <div className="relative flex-1 bg-gray-50 overflow-hidden flex flex-col justify-center items-center p-4">
         {/* Webcam Container */}
         <div className="relative w-full h-full max-w-5xl max-h-full flex items-center justify-center bg-white rounded-3xl shadow-sm border border-gray-200 overflow-hidden aspect-video md:aspect-auto">
             <Webcam
                ref={webcamRef}
                audio={false}
                screenshotFormat="image/jpeg"
                className="absolute w-full h-full object-cover md:object-contain"
                videoConstraints={{ facingMode: "user" }}
            />
            <canvas 
                ref={canvasRef} 
                className="absolute w-full h-full object-cover md:object-contain pointer-events-none"
            />
         </div>

         {/* Phase Indicator (e.g., "DESCENDING") */}
         <div className="absolute bottom-8 left-0 right-0 flex justify-center pointer-events-none z-20">
             <div className="bg-white/90 backdrop-blur px-4 py-1 rounded-full border border-gray-200 shadow-sm">
                 <span className="text-[#778873] font-bold text-xs uppercase tracking-widest">{phase}</span>
             </div>
         </div>

         {/* Live Feedback Toast */}
         {isBadForm && feedbackMessage && (
          <div className="absolute top-8 left-4 right-4 flex justify-center z-30 pointer-events-none animate-bounce">
             <div className="bg-red-600 text-white px-6 py-3 rounded-xl shadow-xl flex items-center gap-3 max-w-md text-center border border-red-700">
                <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                <span className="font-bold text-sm tracking-wide">{feedbackMessage}</span>
             </div>
          </div>
         )}

         {/* Metric Display */}
         <div className="absolute top-8 left-8 z-20 hidden md:block">
             <div className={`
                 backdrop-blur-md p-5 rounded-3xl border shadow-lg transition-all duration-300 min-w-[120px]
                 ${isBadForm ? 'bg-red-50/90 border-red-200' : 'bg-white/90 border-gray-200'}
             `}>
                 <span className={`text-xs font-bold uppercase block mb-1 tracking-wider ${isBadForm ? 'text-red-700' : 'text-slate-500'}`}>
                    {metricLabel}
                 </span>
                 <div className="flex items-center gap-2">
                     <span className={`text-5xl font-bold tracking-tighter ${isBadForm ? 'text-red-600' : 'text-gray-900'}`}>
                         {displayMetric}{metricLabel === 'Angle' ? '°' : ''}
                     </span>
                 </div>
             </div>
         </div>

         {/* Coach Insight */}
         {coachInsight && (
           <div className="absolute top-24 left-4 right-4 flex justify-center z-40 pointer-events-none">
             <div className="bg-white/95 backdrop-blur-md p-4 rounded-2xl shadow-xl border border-gray-200 pointer-events-auto max-w-lg flex items-start gap-4 animate-fade-in-down">
                <div className="p-2.5 bg-[#778873] rounded-xl text-white shrink-0 shadow-sm">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                </div>
                <div className="flex-1">
                    <p className="text-[#778873] font-bold text-xs uppercase tracking-wider mb-1">AI Coach Insight</p>
                    <p className="text-gray-800 text-sm leading-relaxed">
                        {coachInsight}
                    </p>
                </div>
                 <button 
                    onClick={() => setCoachInsight(null)}
                    className="text-slate-400 hover:text-gray-900"
                 >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                 </button>
             </div>
           </div>
         )}

         {/* Loading State */}
         {!window.Pose && (
             <div className="absolute inset-0 flex items-center justify-center bg-white z-30">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#778873] mx-auto mb-4"></div>
                    <p className="text-gray-900 font-medium">Initializing Vision Engine...</p>
                </div>
             </div>
        )}
      </div>

      {/* 3. Bottom Controls */}
      <div className="shrink-0 z-20 p-4 bg-white border-t border-gray-200">
          <div className="max-w-xl mx-auto flex flex-col md:flex-row gap-3">
               <Button 
                   fullWidth 
                   onClick={handleDeepAnalysis}
                   disabled={isAnalyzing}
                   variant="outline"
                   icon={isAnalyzing ? <div className="animate-spin h-5 w-5 border-2 border-[#778873] rounded-full border-t-transparent"/> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>}
               >
                   {isAnalyzing ? "Analyzing..." : "Analyze Posture"}
               </Button>

               <Button 
                   fullWidth 
                   variant="primary" 
                   onClick={handleFinish}
               >
                   End Session
               </Button>
          </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Dashboard } from './components/Dashboard';
import { SessionView } from './components/SessionView';
import { Header } from './components/Header';
import { ReportCard } from './components/ReportCard';
import { Session, ViewState } from './types';
import { GoogleGenAI } from "@google/genai";

function App() {
  const [view, setView] = useState<ViewState>(ViewState.DASHBOARD);
  // Local state for sessions instead of Firestore
  const [sessions, setSessions] = useState<Session[]>([]);
  // Temp state for report view
  const [currentSession, setCurrentSession] = useState<Session | null>(null);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);

  const handleStartSession = () => {
    setView(ViewState.SESSION);
  };

  const handleBackToDashboard = () => {
    setView(ViewState.DASHBOARD);
  }

  const handleSessionComplete = async (data: any) => {
    setIsGeneratingReport(true);
    let summary = "Session analysis unavailable.";

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Act as a Physiotherapist. Analyze this patient data: 
            Total Reps: ${data.reps}
            Average Knee Angle: ${data.averageAngle} degrees
            Duration: ${data.durationSeconds} seconds
            Form Accuracy: ${data.accuracyScore}%

            Write a 3-sentence clinical observation for their doctor, focusing on stability and consistency.`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
        });
        if (response.text) {
            summary = response.text;
        }
    } catch (e) {
        console.error("AI Generation failed", e);
        summary = "Session completed. Unable to generate clinical observation at this time.";
    }

    const newSession: Session = {
        id: Date.now().toString(),
        userId: 'local-user',
        timestamp: new Date(),
        durationSeconds: data.durationSeconds,
        exercises: data.exercises,
        painLevel: data.painLevel,
        accuracyScore: data.accuracyScore,
        reps: data.reps,
        averageAngle: data.averageAngle,
        aiSummary: summary
    };

    setCurrentSession(newSession);
    setView(ViewState.REPORT);
    setIsGeneratingReport(false);
  }

  const handleReportClose = () => {
    if (currentSession) {
        setSessions(prev => [currentSession, ...prev]);
        setCurrentSession(null);
    }
    setView(ViewState.DASHBOARD);
  };

  return (
    <div className="min-h-screen bg-white font-sans selection:bg-[#778873] selection:text-white text-gray-900">
      {view === ViewState.DASHBOARD && (
        <Header />
      )}

      <main>
        {view === ViewState.DASHBOARD && (
          <Dashboard sessions={sessions} onStartSession={handleStartSession} />
        )}

        {view === ViewState.SESSION && (
            <>
            {isGeneratingReport ? (
                <div className="fixed inset-0 bg-white/95 flex flex-col items-center justify-center z-[60] backdrop-blur-sm">
                    <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-[#778873] mb-6"></div>
                    <h2 className="text-2xl font-bold text-gray-900 font-display">Generating Clinical Report...</h2>
                    <p className="text-slate-500 mt-2">Dr. AI is analyzing your biomechanics.</p>
                </div>
            ) : (
                <SessionView 
                    onExit={handleBackToDashboard}
                    onSave={handleSessionComplete}
                />
            )}
            </>
        )}

        {view === ViewState.REPORT && currentSession && (
            <ReportCard 
                session={currentSession}
                onClose={handleReportClose}
            />
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

const EXERCISE_OPTIONS = [
  'Squats',
  'Pushups',
  'Lunges',
  'Plank',
];

// --- 4. Threshold Dictionary ---
const EXERCISE_RULES = {
  Squats: {
    type: 'REP',
    metric: 'Angle',
    // Front View Rules (Knee Angle)
    front: { start: 165, active: 130 },
    // Lateral View Rules (Hip Angle: Shoulder-Hip-Knee)
    lateral: { start: 160, active: 100 }, 
  },
  Pushups: {
    type: 'REP',
    metric: 'Elbow Angle',
    // Usually lateral
    lateral: { start: 160, active: 90 },
    front: { start: 160, active: 90 }, // Fallback
  },
  Lunges: {
    type: 'REP',
    metric: 'Knee Drop',
    // Normalized Y difference between back knee and ankle
    // Standing: Large diff (leg straight), Lunge: Small diff (knee near ground)
    front: { start: 0.25, active: 0.1 }, 
    lateral: { start: 0.25, active: 0.1 },
  },
  Plank: {
    type: 'DURATION',
    metric: 'Body Alignment',
    // Shoulder-Hip-Knee Angle
    minAngle: 165,
    maxAngle: 195,
  }
};

type ExerciseState = 'START' | 'ACTIVE';

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [currentExercise, setCurrentExercise] = useState('Squats');
  const [repCount, setRepCount] = useState(0);
  const [displayMetric, setDisplayMetric] = useState<number>(0); 
  const [metricLabel, setMetricLabel] = useState('Angle');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');
  const [isBadForm, setIsBadForm] = useState(false);

  // State Machine Indicators
  const [exerciseState, setExerciseState] = useState<ExerciseState>('START');
  const [holdTimer, setHoldTimer] = useState(0);

  // Deep Analysis State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });
  const angleSumRef = useRef(0);
  const angleFrameCountRef = useRef(0);

  // Tracking Refs (Avoiding stale closures)
  const stateRef = useRef<ExerciseState>('START');
  const lastRepTimeRef = useRef<number>(0);
  const activeStartTimeRef = useRef<number>(0);
  const lastTimerTickRef = useRef<number>(0);

  // --- Geometry Helpers ---
  const calculateAngle = (a: any, b: any, c: any) => {
    if (!a || !b || !c) return 180;
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);
    if (angle > 180.0) angle = 360 - angle;
    return Math.round(angle);
  };

  const getDominantSide = (landmarks: any[]) => {
    const leftVis = landmarks[11].visibility + landmarks[23].visibility + landmarks[25].visibility;
    const rightVis = landmarks[12].visibility + landmarks[24].visibility + landmarks[26].visibility;
    return leftVis > rightVis ? 'LEFT' : 'RIGHT';
  };

  const checkPlankForm = (shoulder: any, hip: any, knee: any) => {
    const angle = calculateAngle(shoulder, hip, knee);
    const rules = EXERCISE_RULES.Plank;
    return angle >= rules.minAngle && angle <= rules.maxAngle;
  };

  useEffect(() => {
    // Reset
    setRepCount(0);
    setHoldTimer(0);
    setFeedbackMessage('');
    setIsBadForm(false);
    stateRef.current = 'START';
    setExerciseState('START');
    statsRef.current = { goodFrames: 0, totalFrames: 0 };
    angleSumRef.current = 0;
    angleFrameCountRef.current = 0;
  }, [currentExercise]);

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;
      if (!results.poseLandmarks) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      const lm = results.poseLandmarks;

      // --- 2. Fix Lateral View Counting ---
      // Determine visible side
      const side = getDominantSide(lm);
      const isLeft = side === 'LEFT';

      // Select Landmarks based on side
      const shoulder = isLeft ? lm[11] : lm[12];
      const hip = isLeft ? lm[23] : lm[24];
      const knee = isLeft ? lm[25] : lm[26];
      const ankle = isLeft ? lm[27] : lm[28];
      const elbow = isLeft ? lm[13] : lm[14];
      const wrist = isLeft ? lm[15] : lm[16];

      // Detect if Lateral View (Shoulder width is small)
      const shoulderWidth = Math.abs(lm[11].x - lm[12].x);
      const isLateral = shoulderWidth < 0.15; // Threshold for side profile

      let currentMetric = 0;
      let formError = '';
      let isFormGood = true;

      // --- Exercise Logic Switch ---
      switch(currentExercise) {
        case 'Squats': {
            const rules = EXERCISE_RULES.Squats;

            // Critical: Metric changes based on view
            // Front: Knee Angle (Hip-Knee-Ankle)
            // Lateral: Hip Angle (Shoulder-Hip-Knee) for Torso-to-Thigh tracking
            if (isLateral) {
                setMetricLabel('Hip Angle');
                currentMetric = calculateAngle(shoulder, hip, knee);
            } else {
                setMetricLabel('Knee Angle');
                currentMetric = calculateAngle(hip, knee, ankle);
            }
            setDisplayMetric(currentMetric);

            // Thresholds
            const thresholds = isLateral ? rules.lateral : rules.front;

            // --- 1. Universal State Machine for Reps ---
            if (stateRef.current === 'START') {
                // Check if we entered Active zone (went down)
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                // Check if we returned to Start zone (stood up)
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    const durationInActive = now - activeStartTimeRef.current;
                    const timeSinceLastRep = now - lastRepTimeRef.current;

                    // Debounce: Must hold active for 0.2s AND 1s since last rep
                    if (durationInActive > 200 && timeSinceLastRep > 1000) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }

                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }

            // Simple Knee Valgus Check (Front only)
            if (!isLateral) {
                const hipSep = Math.abs(lm[23].x - lm[24].x);
                const kneeSep = Math.abs(lm[25].x - lm[26].x);
                if (kneeSep < hipSep * 0.7) {
                    formError = "Push knees outward";
                    isFormGood = false;
                }
            }
            break;
        }

        case 'Pushups': {
            setMetricLabel('Elbow Angle');
            currentMetric = calculateAngle(shoulder, elbow, wrist);
            setDisplayMetric(currentMetric);

            const rules = EXERCISE_RULES.Pushups;
            const thresholds = rules.lateral; // Use lateral rules primarily

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    if ((now - activeStartTimeRef.current > 200) && (now - lastRepTimeRef.current > 1000)) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }

        case 'Lunges': {
            setMetricLabel('Knee Drop');
            // Logic: Measure Y-distance between back knee and back ankle
            // We use the 'other' leg for the back leg logic usually, or detect which leg is back.
            // Simplified: Use the leg that has the LOWEST knee (highest Y value)
            const leftKneeY = lm[25].y;
            const rightKneeY = lm[26].y;
            // Back knee is the one closer to the ground (higher Y)
            const backKneeIndex = leftKneeY > rightKneeY ? 25 : 26;
            const backAnkleIndex = leftKneeY > rightKneeY ? 27 : 28;

            const bk = lm[backKneeIndex];
            const ba = lm[backAnkleIndex];

            // Distance normalized. Small distance = Knee on ground.
            const dist = Math.abs(bk.y - ba.y); 
            currentMetric = Math.round(dist * 100); // Display as relative unit
            setDisplayMetric(currentMetric);

            const rules = EXERCISE_RULES.Lunges;
            const thresholds = rules.front; // Use generic thresholds

            if (stateRef.current === 'START') {
                // Active = Knee Close to Ankle (Small Distance)
                if (dist <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                // Start = Knee Far from Ankle (Standing)
                if (dist >= thresholds.start) {
                    const now = Date.now();
                    if ((now - activeStartTimeRef.current > 200) && (now - lastRepTimeRef.current > 1000)) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }

        case 'Plank': {
            setMetricLabel('Align Angle');
            // 3. Fix Plank Timer Logic
            const alignmentAngle = calculateAngle(shoulder, hip, knee);
            currentMetric = alignmentAngle;
            setDisplayMetric(currentMetric);

            const isAligned = checkPlankForm(shoulder, hip, knee);

            if (isAligned) {
                const now = Date.now();
                if (now - lastTimerTickRef.current >= 1000) {
                    setHoldTimer(t => t + 1);
                    lastTimerTickRef.current = now;
                }
                if (stateRef.current !== 'ACTIVE') {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                }
            } else {
                formError = "Align Hips to Resume";
                isFormGood = false;
                if (stateRef.current !== 'START') {
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }
      }

      // Collect data for average calc
      if (currentExercise === 'Squats' && currentMetric > 0) {
        angleSumRef.current += currentMetric;
        angleFrameCountRef.current += 1;
      }
      statsRef.current.totalFrames++;
      if (isFormGood) statsRef.current.goodFrames++;

      setIsBadForm(!isFormGood);
      setFeedbackMessage(formError);

      // --- Draw Skeleton ---
      // Use Sage for good form, Red for bad/correction
      const skeletonColor = !isFormGood ? '#EF4444' : '#778873';
      const landmarkColor = !isFormGood ? '#EF4444' : '#D2DCB6';

      // Draw standard connectors
      window.drawConnectors(canvasCtx, lm, window.POSE_CONNECTIONS,
          { color: skeletonColor, lineWidth: 4 });

      // Highlight specific joints based on exercise to guide user attention
      window.drawLandmarks(canvasCtx, [shoulder, hip, knee, ankle],
          { color: landmarkColor, lineWidth: 4, radius: 6 });

      canvasCtx.restore();
    };

    const initializePose = async () => {
        if (window.Pose) {
            pose = new window.Pose({
                locateFile: (file: string) => {
                    return `https://cdn.jsdelivr.net/npm/@mediapipe/pose@0.5.1675469404/${file}`;
                }
            });

            pose.setOptions({
                modelComplexity: 1,
                smoothLandmarks: true,
                enableSegmentation: false,
                minDetectionConfidence: 0.5,
                minTrackingConfidence: 0.5
            });

            pose.onResults(onResults);
            if (pose.initialize) await pose.initialize();
            detect();
        }
    };

    const detect = async () => {
      if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4 && pose) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    initializePose();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, [currentExercise]);

  const handleDeepAnalysis = async () => {
    if (!webcamRef.current) return;
    setIsAnalyzing(true);
    setCoachInsight(null);

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            setCoachInsight("Camera unavailable.");
            setIsAnalyzing(false);
            return;
        }

        const base64Data = imageSrc.split(',')[1];
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
                    { text: `Analyze this ${currentExercise} form. Is the spine neutral? Give one specific correction.` }
                ]
            }
        });
        setCoachInsight(response.text || "Analysis result unavailable.");

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    onSave({
        durationSeconds,
        exercises: [currentExercise],
        painLevel: 2, 
        accuracyScore: accuracy,
        reps: currentExercise === 'Plank' ? 0 : repCount, 
        averageAngle: Math.round(angleSumRef.current / (angleFrameCountRef.current || 1))
    });
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-[100dvh]">

      {/* 1. Header Bar */}
      <div className="shrink-0 z-20 p-4 flex justify-between items-center bg-white/95 backdrop-blur-sm border-b border-gray-100">
         <div className="flex items-center gap-4 flex-1">
             <select 
                value={currentExercise}
                onChange={(e) => setCurrentExercise(e.target.value)}
                className="bg-white text-[#778873] border border-gray-200 rounded-xl px-4 py-2 text-sm font-bold uppercase tracking-wider focus:outline-none focus:ring-2 focus:ring-[#778873]/50 focus:border-[#778873] cursor-pointer appearance-none shadow-sm transition-all hover:border-[#778873]"
             >
                {EXERCISE_OPTIONS.map(ex => (
                    <option key={ex} value={ex}>{ex}</option>
                ))}
             </select>

             <div className="w-px h-6 bg-gray-200"></div>

             {currentExercise === 'Plank' ? (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{formatTime(holdTimer)}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Hold Time</span>
                </div>
             ) : (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{repCount}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Reps</span>
                </div>
             )}
         </div>
         <button 
            onClick={onExit}
            className="text-slate-400 p-2 bg-gray-50 rounded-full hover:bg-gray-100 hover:text-gray-900 transition-colors"
         >
             <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
         </button>
      </div>

      {/* 2. Main Vision Area */}
      <div className="relative flex-1 bg-gray-50 overflow-hidden flex flex-col justify-center items-center p-4">
         <div className="relative w-full h-full max-w-5xl max-h-full flex items-center justify-center bg-white rounded-3xl shadow-sm border border-gray-200 overflow-hidden aspect-video md:aspect-auto">
             <Webcam
                ref={webcamRef}
                audio={false}
                screenshotFormat="image/jpeg"
                className="absolute w-full h-full object-cover md:object-contain"
                videoConstraints={{ facingMode: "user" }}
            />
            <canvas 
                ref={canvasRef} 
                className="absolute w-full h-full object-cover md:object-contain pointer-events-none"
            />
         </div>

         {/* Phase Indicator */}
         <div className="absolute bottom-8 left-0 right-0 flex justify-center pointer-events-none z-20">
             <div className="bg-white/90 backdrop-blur px-4 py-1 rounded-full border border-gray-200 shadow-sm">
                 <span className={`font-bold text-xs uppercase tracking-widest ${exerciseState === 'ACTIVE' ? 'text-[#778873]' : 'text-slate-400'}`}>
                    {exerciseState === 'ACTIVE' ? 'Active Phase' : 'Start Phase'}
                 </span>
             </div>
         </div>

         {/* Live Feedback Toast */}
         {isBadForm && feedbackMessage && (
          <div className="absolute top-8 left-4 right-4 flex justify-center z-30 pointer-events-none animate-bounce">
             <div className="bg-red-600 text-white px-6 py-3 rounded-xl shadow-xl flex items-center gap-3 max-w-md text-center border border-red-700">
                <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                <span className="font-bold text-sm tracking-wide">{feedbackMessage}</span>
             </div>
          </div>
         )}

         {/* Metric Display */}
         <div className="absolute top-8 left-8 z-20 hidden md:block">
             <div className={`
                 backdrop-blur-md p-5 rounded-3xl border shadow-lg transition-all duration-300 min-w-[120px]
                 ${isBadForm ? 'bg-red-50/90 border-red-200' : 'bg-white/90 border-gray-200'}
             `}>
                 <span className={`text-xs font-bold uppercase block mb-1 tracking-wider ${isBadForm ? 'text-red-700' : 'text-slate-500'}`}>
                    {metricLabel}
                 </span>
                 <div className="flex items-center gap-2">
                     <span className={`text-5xl font-bold tracking-tighter ${isBadForm ? 'text-red-600' : 'text-gray-900'}`}>
                         {displayMetric}{metricLabel === 'Angle' || metricLabel === 'Align Angle' || metricLabel === 'Elbow Angle' || metricLabel === 'Hip Angle' ? '°' : ''}
                     </span>
                 </div>
             </div>
         </div>

         {/* Coach Insight */}
         {coachInsight && (
           <div className="absolute top-24 left-4 right-4 flex justify-center z-40 pointer-events-none">
             <div className="bg-white/95 backdrop-blur-md p-4 rounded-2xl shadow-xl border border-gray-200 pointer-events-auto max-w-lg flex items-start gap-4 animate-fade-in-down">
                <div className="p-2.5 bg-[#778873] rounded-xl text-white shrink-0 shadow-sm">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                </div>
                <div className="flex-1">
                    <p className="text-[#778873] font-bold text-xs uppercase tracking-wider mb-1">AI Coach Insight</p>
                    <p className="text-gray-800 text-sm leading-relaxed">
                        {coachInsight}
                    </p>
                </div>
                 <button 
                    onClick={() => setCoachInsight(null)}
                    className="text-slate-400 hover:text-gray-900"
                 >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                 </button>
             </div>
           </div>
         )}

         {/* Loading State */}
         {!window.Pose && (
             <div className="absolute inset-0 flex items-center justify-center bg-white z-30">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#778873] mx-auto mb-4"></div>
                    <p className="text-gray-900 font-medium">Initializing Vision Engine...</p>
                </div>
             </div>
        )}
      </div>

      {/* 3. Bottom Controls */}
      <div className="shrink-0 z-20 p-4 bg-white border-t border-gray-200">
          <div className="max-w-xl mx-auto flex flex-col md:flex-row gap-3">
               <Button 
                   fullWidth 
                   onClick={handleDeepAnalysis}
                   disabled={isAnalyzing}
                   variant="outline"
                   icon={isAnalyzing ? <div className="animate-spin h-5 w-5 border-2 border-[#778873] rounded-full border-t-transparent"/> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>}
               >
                   {isAnalyzing ? "Analyzing..." : "Analyze Posture"}
               </Button>

               <Button 
                   fullWidth 
                   variant="primary" 
                   onClick={handleFinish}
               >
                   End Session
               </Button>
          </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

const EXERCISE_OPTIONS = [
  'Squats',
  'Pushups',
  'Lateral Lunge',
  'Plank',
];

// --- 4. Threshold Dictionary ---
const EXERCISE_RULES = {
  Squats: {
    type: 'REP',
    metric: 'Angle',
    front: { start: 165, active: 130 },
    lateral: { start: 160, active: 100 }, 
  },
  Pushups: {
    type: 'REP',
    metric: 'Elbow Angle',
    lateral: { start: 160, active: 90 },
    front: { start: 160, active: 90 },
  },
  'Lateral Lunge': {
    type: 'REP',
    metric: 'Working Knee',
    // Asymmetric Rules
    startAngle: 165,    // Both legs straight
    workingMax: 110,    // Bent leg max angle
    staticMin: 150,     // Straight leg min angle
    hipDropThreshold: 0.1 // ~10-15% screen height drop
  },
  Plank: {
    type: 'DURATION',
    metric: 'Body Alignment',
    minAngle: 165,
    maxAngle: 195,
  }
};

type ExerciseState = 'START' | 'ACTIVE';

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [currentExercise, setCurrentExercise] = useState('Squats');
  const [repCount, setRepCount] = useState(0);
  const [displayMetric, setDisplayMetric] = useState<number>(0); 
  const [metricLabel, setMetricLabel] = useState('Angle');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');
  const [isBadForm, setIsBadForm] = useState(false);

  // State Machine Indicators
  const [exerciseState, setExerciseState] = useState<ExerciseState>('START');
  const [holdTimer, setHoldTimer] = useState(0);

  // Analysis & Countdown State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [showFlash, setShowFlash] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });
  const angleSumRef = useRef(0);
  const angleFrameCountRef = useRef(0);

  // Tracking Refs
  const stateRef = useRef<ExerciseState>('START');
  const lastRepTimeRef = useRef<number>(0);
  const activeStartTimeRef = useRef<number>(0);
  const lastTimerTickRef = useRef<number>(0);
  const standingHipYRef = useRef<number>(0); // Reference for hip drop

  // --- Geometry Helpers ---
  const calculateAngle = (a: any, b: any, c: any) => {
    if (!a || !b || !c) return 180;
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);
    if (angle > 180.0) angle = 360 - angle;
    return Math.round(angle);
  };

  const getDominantSide = (landmarks: any[]) => {
    const leftVis = landmarks[11].visibility + landmarks[23].visibility + landmarks[25].visibility;
    const rightVis = landmarks[12].visibility + landmarks[24].visibility + landmarks[26].visibility;
    return leftVis > rightVis ? 'LEFT' : 'RIGHT';
  };

  const checkPlankForm = (shoulder: any, hip: any, knee: any) => {
    const angle = calculateAngle(shoulder, hip, knee);
    const rules = EXERCISE_RULES.Plank;
    return angle >= rules.minAngle && angle <= rules.maxAngle;
  };

  // --- Analysis Countdown Effect ---
  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (countdown !== null && countdown > 0) {
      timer = setTimeout(() => setCountdown(c => (c !== null ? c - 1 : null)), 1000);
    } else if (countdown === 0) {
      // Trigger Capture
      setCountdown(null);
      performCaptureAndAnalysis();
    }
    return () => clearTimeout(timer);
  }, [countdown]);

  useEffect(() => {
    // Reset on exercise change
    setRepCount(0);
    setHoldTimer(0);
    setFeedbackMessage('');
    setIsBadForm(false);
    stateRef.current = 'START';
    setExerciseState('START');
    statsRef.current = { goodFrames: 0, totalFrames: 0 };
    angleSumRef.current = 0;
    angleFrameCountRef.current = 0;
    standingHipYRef.current = 0;
  }, [currentExercise]);

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;
      if (!results.poseLandmarks) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      const lm = results.poseLandmarks;

      // Select Landmarks based on side (for Squats/Pushups/Planks)
      const side = getDominantSide(lm);
      const isLeft = side === 'LEFT';

      const shoulder = isLeft ? lm[11] : lm[12];
      const hip = isLeft ? lm[23] : lm[24];
      const knee = isLeft ? lm[25] : lm[26];
      const ankle = isLeft ? lm[27] : lm[28];
      const elbow = isLeft ? lm[13] : lm[14];
      const wrist = isLeft ? lm[15] : lm[16];

      // Detect Lateral View
      const shoulderWidth = Math.abs(lm[11].x - lm[12].x);
      const isLateral = shoulderWidth < 0.15; 

      let currentMetric = 0;
      let formError = '';
      let isFormGood = true;

      // --- Exercise Logic Switch ---
      switch(currentExercise) {
        case 'Squats': {
            const rules = EXERCISE_RULES.Squats;
            if (isLateral) {
                setMetricLabel('Hip Angle');
                currentMetric = calculateAngle(shoulder, hip, knee);
            } else {
                setMetricLabel('Knee Angle');
                currentMetric = calculateAngle(hip, knee, ankle);
            }
            setDisplayMetric(currentMetric);

            const thresholds = isLateral ? rules.lateral : rules.front;

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    const durationInActive = now - activeStartTimeRef.current;
                    const timeSinceLastRep = now - lastRepTimeRef.current;

                    if (durationInActive > 200 && timeSinceLastRep > 1000) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }

            if (!isLateral) {
                const hipSep = Math.abs(lm[23].x - lm[24].x);
                const kneeSep = Math.abs(lm[25].x - lm[26].x);
                if (kneeSep < hipSep * 0.7) {
                    formError = "Push knees outward";
                    isFormGood = false;
                }
            }
            break;
        }

        case 'Pushups': {
            setMetricLabel('Elbow Angle');
            currentMetric = calculateAngle(shoulder, elbow, wrist);
            setDisplayMetric(currentMetric);

            const rules = EXERCISE_RULES.Pushups;
            const thresholds = rules.lateral;

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    if ((now - activeStartTimeRef.current > 200) && (now - lastRepTimeRef.current > 1000)) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }

        case 'Lateral Lunge': {
            setMetricLabel('Working Knee');
            const rules = EXERCISE_RULES['Lateral Lunge'];

            const lKneeAngle = calculateAngle(lm[23], lm[25], lm[27]);
            const rKneeAngle = calculateAngle(lm[24], lm[26], lm[28]);

            // Average Hip Y (normalized 0-1, higher is lower on screen)
            const currentHipY = (lm[23].y + lm[24].y) / 2;

            // Determine Working Leg (the one bending)
            const workingKneeAngle = Math.min(lKneeAngle, rKneeAngle);
            const staticKneeAngle = Math.max(lKneeAngle, rKneeAngle);

            currentMetric = workingKneeAngle;
            setDisplayMetric(currentMetric);

            if (stateRef.current === 'START') {
                // Determine Reference Standing Height (Lowest Y value seen in Start phase)
                if (lKneeAngle > rules.startAngle && rKneeAngle > rules.startAngle) {
                    // Update reference if standing taller (smaller Y)
                    if (standingHipYRef.current === 0 || currentHipY < standingHipYRef.current) {
                        standingHipYRef.current = currentHipY;
                    }
                }

                // Transition to Active: Working Leg Bent + Static Leg Straight + Hip Drop
                const hipDrop = currentHipY - standingHipYRef.current; // Positive delta = drop

                if (workingKneeAngle < rules.workingMax && 
                    staticKneeAngle > rules.staticMin &&
                    hipDrop > rules.hipDropThreshold) {
                        stateRef.current = 'ACTIVE';
                        setExerciseState('ACTIVE');
                        activeStartTimeRef.current = Date.now();
                }

            } else if (stateRef.current === 'ACTIVE') {
                // Transition to Start: Both legs straight
                if (lKneeAngle > rules.startAngle && rKneeAngle > rules.startAngle) {
                     const now = Date.now();
                     const durationInActive = now - activeStartTimeRef.current;
                     const timeSinceLastRep = now - lastRepTimeRef.current;

                     if (durationInActive > 300 && timeSinceLastRep > 1000) {
                         setRepCount(c => c + 1);
                         lastRepTimeRef.current = now;
                     }
                     stateRef.current = 'START';
                     setExerciseState('START');
                }
            }
            break;
        }

        case 'Plank': {
            setMetricLabel('Align Angle');
            const alignmentAngle = calculateAngle(shoulder, hip, knee);
            currentMetric = alignmentAngle;
            setDisplayMetric(currentMetric);

            const isAligned = checkPlankForm(shoulder, hip, knee);

            if (isAligned) {
                const now = Date.now();
                if (now - lastTimerTickRef.current >= 1000) {
                    setHoldTimer(t => t + 1);
                    lastTimerTickRef.current = now;
                }
                if (stateRef.current !== 'ACTIVE') {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                }
            } else {
                formError = "Align Hips to Resume";
                isFormGood = false;
                if (stateRef.current !== 'START') {
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }
      }

      // Collect data for average calc
      if (currentExercise === 'Squats' && currentMetric > 0) {
        angleSumRef.current += currentMetric;
        angleFrameCountRef.current += 1;
      }
      statsRef.current.totalFrames++;
      if (isFormGood) statsRef.current.goodFrames++;

      setIsBadForm(!isFormGood);
      setFeedbackMessage(formError);

      const skeletonColor = !isFormGood ? '#EF4444' : '#778873';
      const landmarkColor = !isFormGood ? '#EF4444' : '#D2DCB6';

      window.drawConnectors(canvasCtx, lm, window.POSE_CONNECTIONS,
          { color: skeletonColor, lineWidth: 4 });

      window.drawLandmarks(canvasCtx, [shoulder, hip, knee, ankle],
          { color: landmarkColor, lineWidth: 4, radius: 6 });

      canvasCtx.restore();
    };

    const initializePose = async () => {
        if (window.Pose) {
            pose = new window.Pose({
                locateFile: (file: string) => {
                    return `https://cdn.jsdelivr.net/npm/@mediapipe/pose@0.5.1675469404/${file}`;
                }
            });

            pose.setOptions({
                modelComplexity: 1,
                smoothLandmarks: true,
                enableSegmentation: false,
                minDetectionConfidence: 0.5,
                minTrackingConfidence: 0.5
            });

            pose.onResults(onResults);
            if (pose.initialize) await pose.initialize();
            detect();
        }
    };

    const detect = async () => {
      if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4 && pose) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    initializePose();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, [currentExercise]);

  const startAnalysisCountdown = () => {
    setIsAnalyzing(true);
    setCoachInsight(null);
    setCountdown(5); // Start 5s countdown
  };

  const performCaptureAndAnalysis = async () => {
    // Flash Effect
    setShowFlash(true);
    setTimeout(() => setShowFlash(false), 200);

    if (!webcamRef.current) return;

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            setCoachInsight("Camera unavailable.");
            setIsAnalyzing(false);
            return;
        }

        const base64Data = imageSrc.split(',')[1];
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
                    { text: `Analyze this ${currentExercise} form in one short sentence. Is the posture correct?` }
                ]
            }
        });
        setCoachInsight(response.text || "Analysis result unavailable.");

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    onSave({
        durationSeconds,
        exercises: [currentExercise],
        painLevel: 2, 
        accuracyScore: accuracy,
        reps: currentExercise === 'Plank' ? 0 : repCount, 
        averageAngle: Math.round(angleSumRef.current / (angleFrameCountRef.current || 1))
    });
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-[100dvh]">

      {/* 1. Header Bar */}
      <div className="shrink-0 z-20 p-4 flex justify-between items-center bg-white/95 backdrop-blur-sm border-b border-gray-100">
         <div className="flex items-center gap-4 flex-1">
             <select 
                value={currentExercise}
                onChange={(e) => setCurrentExercise(e.target.value)}
                className="bg-white text-[#778873] border border-gray-200 rounded-xl px-4 py-2 text-sm font-bold uppercase tracking-wider focus:outline-none focus:ring-2 focus:ring-[#778873]/50 focus:border-[#778873] cursor-pointer appearance-none shadow-sm transition-all hover:border-[#778873]"
             >
                {EXERCISE_OPTIONS.map(ex => (
                    <option key={ex} value={ex}>{ex}</option>
                ))}
             </select>

             <div className="w-px h-6 bg-gray-200"></div>

             {currentExercise === 'Plank' ? (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{formatTime(holdTimer)}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Hold Time</span>
                </div>
             ) : (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{repCount}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Reps</span>
                </div>
             )}
         </div>
         <button 
            onClick={onExit}
            className="text-slate-400 p-2 bg-gray-50 rounded-full hover:bg-gray-100 hover:text-gray-900 transition-colors"
         >
             <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
         </button>
      </div>

      {/* 2. Main Vision Area */}
      <div className="relative flex-1 bg-gray-50 overflow-hidden flex flex-col justify-center items-center p-4">
         <div className="relative w-full h-full max-w-5xl max-h-full flex items-center justify-center bg-white rounded-3xl shadow-sm border border-gray-200 overflow-hidden aspect-video md:aspect-auto">
             <Webcam
                ref={webcamRef}
                audio={false}
                screenshotFormat="image/jpeg"
                className="absolute w-full h-full object-cover md:object-contain"
                videoConstraints={{ facingMode: "user" }}
            />
            <canvas 
                ref={canvasRef} 
                className="absolute w-full h-full object-cover md:object-contain pointer-events-none"
            />

            {/* Flash Effect Layer */}
            {showFlash && (
                <div className="absolute inset-0 bg-white z-50 animate-pulse pointer-events-none"></div>
            )}

            {/* Countdown Overlay */}
            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-40 backdrop-blur-sm">
                    <div className="text-center text-white">
                        <p className="text-8xl font-bold font-display animate-ping">{countdown}</p>
                        <p className="text-xl font-medium mt-4 uppercase tracking-widest">Get into position!</p>
                    </div>
                </div>
            )}
         </div>

         {/* Phase Indicator */}
         <div className="absolute bottom-8 left-0 right-0 flex justify-center pointer-events-none z-20">
             <div className="bg-white/90 backdrop-blur px-4 py-1 rounded-full border border-gray-200 shadow-sm">
                 <span className={`font-bold text-xs uppercase tracking-widest ${exerciseState === 'ACTIVE' ? 'text-[#778873]' : 'text-slate-400'}`}>
                    {exerciseState === 'ACTIVE' ? 'Active Phase' : 'Start Phase'}
                 </span>
             </div>
         </div>

         {/* Live Feedback Toast */}
         {isBadForm && feedbackMessage && (
          <div className="absolute top-8 left-4 right-4 flex justify-center z-30 pointer-events-none animate-bounce">
             <div className="bg-red-600 text-white px-6 py-3 rounded-xl shadow-xl flex items-center gap-3 max-w-md text-center border border-red-700">
                <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                <span className="font-bold text-sm tracking-wide">{feedbackMessage}</span>
             </div>
          </div>
         )}

         {/* Metric Display */}
         <div className="absolute top-8 left-8 z-20 hidden md:block">
             <div className={`
                 backdrop-blur-md p-5 rounded-3xl border shadow-lg transition-all duration-300 min-w-[120px]
                 ${isBadForm ? 'bg-red-50/90 border-red-200' : 'bg-white/90 border-gray-200'}
             `}>
                 <span className={`text-xs font-bold uppercase block mb-1 tracking-wider ${isBadForm ? 'text-red-700' : 'text-slate-500'}`}>
                    {metricLabel}
                 </span>
                 <div className="flex items-center gap-2">
                     <span className={`text-5xl font-bold tracking-tighter ${isBadForm ? 'text-red-600' : 'text-gray-900'}`}>
                         {displayMetric}°
                     </span>
                 </div>
             </div>
         </div>

         {/* Coach Insight */}
         {coachInsight && (
           <div className="absolute top-24 left-4 right-4 flex justify-center z-40 pointer-events-none">
             <div className="bg-white/95 backdrop-blur-md p-4 rounded-2xl shadow-xl border border-gray-200 pointer-events-auto max-w-lg flex items-start gap-4 animate-fade-in-down">
                <div className="p-2.5 bg-[#778873] rounded-xl text-white shrink-0 shadow-sm">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                </div>
                <div className="flex-1">
                    <p className="text-[#778873] font-bold text-xs uppercase tracking-wider mb-1">AI Coach Insight</p>
                    <p className="text-gray-800 text-sm leading-relaxed">
                        {coachInsight}
                    </p>
                </div>
                 <button 
                    onClick={() => setCoachInsight(null)}
                    className="text-slate-400 hover:text-gray-900"
                 >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                 </button>
             </div>
           </div>
         )}

         {/* Loading State */}
         {!window.Pose && (
             <div className="absolute inset-0 flex items-center justify-center bg-white z-30">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#778873] mx-auto mb-4"></div>
                    <p className="text-gray-900 font-medium">Initializing Vision Engine...</p>
                </div>
             </div>
        )}
      </div>

      {/* 3. Bottom Controls */}
      <div className="shrink-0 z-20 p-4 bg-white border-t border-gray-200">
          <div className="max-w-xl mx-auto flex flex-col md:flex-row gap-3">
               <Button 
                   fullWidth 
                   onClick={startAnalysisCountdown}
                   disabled={isAnalyzing || countdown !== null}
                   variant="outline"
                   icon={isAnalyzing ? <div className="animate-spin h-5 w-5 border-2 border-[#778873] rounded-full border-t-transparent"/> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>}
               >
                   {countdown !== null ? `Capturing in ${countdown}...` : (isAnalyzing ? "Analyzing..." : "Analyze Posture")}
               </Button>

               <Button 
                   fullWidth 
                   variant="primary" 
                   onClick={handleFinish}
               >
                   End Session
               </Button>
          </div>
      </div>
    </div>
  );
};

export interface Session {
  id: string;
  userId: string;
  timestamp: Date;
  durationSeconds: number;
  exercises: string[];
  exerciseStats: Record<string, number>; // Map of Exercise Name -> Count/Seconds
  painLevel: number; // 1-10
  accuracyScore: number; // Percentage
  averageAngle?: number;
  reps?: number;
  aiSummary: string; // Generated by Gemini
}

export interface UserProfile {
  uid: string;
  displayName: string | null;
  email: string | null;
  photoURL: string | null;
}

export enum ViewState {
  DASHBOARD = 'DASHBOARD',
  SESSION = 'SESSION',
  REPORT = 'REPORT',
}

// Global Types
declare global {
  interface Window {
    Pose: any;
    Camera: any;
    drawConnectors: any;
    drawLandmarks: any;
    POSE_CONNECTIONS: any;
    jspdf: any; // PDF Library
  }
}

import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

const EXERCISE_OPTIONS = [
  'Squats',
  'Pushups',
  'Lateral Lunge',
  'Plank',
];

// --- 4. Threshold Dictionary ---
const EXERCISE_RULES = {
  Squats: {
    type: 'REP',
    metric: 'Angle',
    front: { start: 165, active: 130 },
    lateral: { start: 160, active: 100 }, 
  },
  Pushups: {
    type: 'REP',
    metric: 'Elbow Angle',
    lateral: { start: 160, active: 90 },
    front: { start: 160, active: 90 },
  },
  'Lateral Lunge': {
    type: 'REP',
    metric: 'Working Knee',
    startAngle: 165,    
    workingMax: 110,    
    staticMin: 150,     
    hipDropThreshold: 0.1 
  },
  Plank: {
    type: 'DURATION',
    metric: 'Body Alignment',
    minAngle: 165,
    maxAngle: 195,
  }
};

type ExerciseState = 'START' | 'ACTIVE';

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [currentExercise, setCurrentExercise] = useState('Squats');
  const [repCount, setRepCount] = useState(0);
  const [displayMetric, setDisplayMetric] = useState<number>(0); 
  const [metricLabel, setMetricLabel] = useState('Angle');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');
  const [isBadForm, setIsBadForm] = useState(false);

  // Session Accumulation State
  const accumulatedStats = useRef<Record<string, number>>({});

  // State Machine Indicators
  const [exerciseState, setExerciseState] = useState<ExerciseState>('START');
  const [holdTimer, setHoldTimer] = useState(0);

  // Analysis & Countdown State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [showFlash, setShowFlash] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });
  const angleSumRef = useRef(0);
  const angleFrameCountRef = useRef(0);

  // Tracking Refs
  const stateRef = useRef<ExerciseState>('START');
  const lastRepTimeRef = useRef<number>(0);
  const activeStartTimeRef = useRef<number>(0);
  const lastTimerTickRef = useRef<number>(0);
  const standingHipYRef = useRef<number>(0);

  // --- Helpers ---
  const calculateAngle = (a: any, b: any, c: any) => {
    if (!a || !b || !c) return 180;
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);
    if (angle > 180.0) angle = 360 - angle;
    return Math.round(angle);
  };

  const getDominantSide = (landmarks: any[]) => {
    const leftVis = landmarks[11].visibility + landmarks[23].visibility + landmarks[25].visibility;
    const rightVis = landmarks[12].visibility + landmarks[24].visibility + landmarks[26].visibility;
    return leftVis > rightVis ? 'LEFT' : 'RIGHT';
  };

  const checkPlankForm = (shoulder: any, hip: any, knee: any) => {
    const angle = calculateAngle(shoulder, hip, knee);
    const rules = EXERCISE_RULES.Plank;
    return angle >= rules.minAngle && angle <= rules.maxAngle;
  };

  // --- Logic to Switch Exercise & Save Stats ---
  const switchExercise = (newExercise: string) => {
    // 1. Save current stats before switching
    const currentValue = currentExercise === 'Plank' ? holdTimer : repCount;
    if (currentValue > 0) {
      accumulatedStats.current[currentExercise] = (accumulatedStats.current[currentExercise] || 0) + currentValue;
    }

    // 2. Switch
    setCurrentExercise(newExercise);
  };

  useEffect(() => {
    // Reset Counters on exercise change
    setRepCount(0);
    setHoldTimer(0);
    setFeedbackMessage('');
    setIsBadForm(false);
    stateRef.current = 'START';
    setExerciseState('START');
    // Note: We do NOT reset accumulatedStats here

    // Reset tracking refs specific to exercise mechanics
    standingHipYRef.current = 0;
  }, [currentExercise]);

  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (countdown !== null && countdown > 0) {
      timer = setTimeout(() => setCountdown(c => (c !== null ? c - 1 : null)), 1000);
    } else if (countdown === 0) {
      setCountdown(null);
      performCaptureAndAnalysis();
    }
    return () => clearTimeout(timer);
  }, [countdown]);

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;
      if (!results.poseLandmarks) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      const lm = results.poseLandmarks;

      const side = getDominantSide(lm);
      const isLeft = side === 'LEFT';

      const shoulder = isLeft ? lm[11] : lm[12];
      const hip = isLeft ? lm[23] : lm[24];
      const knee = isLeft ? lm[25] : lm[26];
      const ankle = isLeft ? lm[27] : lm[28];
      const elbow = isLeft ? lm[13] : lm[14];
      const wrist = isLeft ? lm[15] : lm[16];

      const shoulderWidth = Math.abs(lm[11].x - lm[12].x);
      const isLateral = shoulderWidth < 0.15; 

      let currentMetric = 0;
      let formError = '';
      let isFormGood = true;

      switch(currentExercise) {
        case 'Squats': {
            const rules = EXERCISE_RULES.Squats;
            if (isLateral) {
                setMetricLabel('Hip Angle');
                currentMetric = calculateAngle(shoulder, hip, knee);
            } else {
                setMetricLabel('Knee Angle');
                currentMetric = calculateAngle(hip, knee, ankle);
            }
            setDisplayMetric(currentMetric);

            const thresholds = isLateral ? rules.lateral : rules.front;

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    const durationInActive = now - activeStartTimeRef.current;
                    const timeSinceLastRep = now - lastRepTimeRef.current;

                    if (durationInActive > 200 && timeSinceLastRep > 1000) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }

            if (!isLateral) {
                const hipSep = Math.abs(lm[23].x - lm[24].x);
                const kneeSep = Math.abs(lm[25].x - lm[26].x);
                if (kneeSep < hipSep * 0.7) {
                    formError = "Push knees outward";
                    isFormGood = false;
                }
            }
            break;
        }

        case 'Pushups': {
            setMetricLabel('Elbow Angle');
            currentMetric = calculateAngle(shoulder, elbow, wrist);
            setDisplayMetric(currentMetric);

            const rules = EXERCISE_RULES.Pushups;
            const thresholds = rules.lateral;

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    if ((now - activeStartTimeRef.current > 200) && (now - lastRepTimeRef.current > 1000)) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }

        case 'Lateral Lunge': {
            setMetricLabel('Working Knee');
            const rules = EXERCISE_RULES['Lateral Lunge'];

            const lKneeAngle = calculateAngle(lm[23], lm[25], lm[27]);
            const rKneeAngle = calculateAngle(lm[24], lm[26], lm[28]);
            const currentHipY = (lm[23].y + lm[24].y) / 2;
            const workingKneeAngle = Math.min(lKneeAngle, rKneeAngle);
            const staticKneeAngle = Math.max(lKneeAngle, rKneeAngle);

            currentMetric = workingKneeAngle;
            setDisplayMetric(currentMetric);

            if (stateRef.current === 'START') {
                if (lKneeAngle > rules.startAngle && rKneeAngle > rules.startAngle) {
                    if (standingHipYRef.current === 0 || currentHipY < standingHipYRef.current) {
                        standingHipYRef.current = currentHipY;
                    }
                }
                const hipDrop = currentHipY - standingHipYRef.current; 

                if (workingKneeAngle < rules.workingMax && 
                    staticKneeAngle > rules.staticMin &&
                    hipDrop > rules.hipDropThreshold) {
                        stateRef.current = 'ACTIVE';
                        setExerciseState('ACTIVE');
                        activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (lKneeAngle > rules.startAngle && rKneeAngle > rules.startAngle) {
                     const now = Date.now();
                     const durationInActive = now - activeStartTimeRef.current;
                     const timeSinceLastRep = now - lastRepTimeRef.current;

                     if (durationInActive > 300 && timeSinceLastRep > 1000) {
                         setRepCount(c => c + 1);
                         lastRepTimeRef.current = now;
                     }
                     stateRef.current = 'START';
                     setExerciseState('START');
                }
            }
            break;
        }

        case 'Plank': {
            setMetricLabel('Align Angle');
            const alignmentAngle = calculateAngle(shoulder, hip, knee);
            currentMetric = alignmentAngle;
            setDisplayMetric(currentMetric);

            const isAligned = checkPlankForm(shoulder, hip, knee);

            if (isAligned) {
                const now = Date.now();
                if (now - lastTimerTickRef.current >= 1000) {
                    setHoldTimer(t => t + 1);
                    lastTimerTickRef.current = now;
                }
                if (stateRef.current !== 'ACTIVE') {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                }
            } else {
                formError = "Align Hips to Resume";
                isFormGood = false;
                if (stateRef.current !== 'START') {
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }
      }

      if (currentExercise === 'Squats' && currentMetric > 0) {
        angleSumRef.current += currentMetric;
        angleFrameCountRef.current += 1;
      }
      statsRef.current.totalFrames++;
      if (isFormGood) statsRef.current.goodFrames++;

      setIsBadForm(!isFormGood);
      setFeedbackMessage(formError);

      const skeletonColor = !isFormGood ? '#EF4444' : '#778873';
      const landmarkColor = !isFormGood ? '#EF4444' : '#D2DCB6';

      window.drawConnectors(canvasCtx, lm, window.POSE_CONNECTIONS,
          { color: skeletonColor, lineWidth: 4 });

      window.drawLandmarks(canvasCtx, [shoulder, hip, knee, ankle],
          { color: landmarkColor, lineWidth: 4, radius: 6 });

      canvasCtx.restore();
    };

    const initializePose = async () => {
        if (window.Pose) {
            pose = new window.Pose({
                locateFile: (file: string) => {
                    return `https://cdn.jsdelivr.net/npm/@mediapipe/pose@0.5.1675469404/${file}`;
                }
            });

            pose.setOptions({
                modelComplexity: 1,
                smoothLandmarks: true,
                enableSegmentation: false,
                minDetectionConfidence: 0.5,
                minTrackingConfidence: 0.5
            });

            pose.onResults(onResults);
            if (pose.initialize) await pose.initialize();
            detect();
        }
    };

    const detect = async () => {
      if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4 && pose) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    initializePose();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, [currentExercise]);

  const startAnalysisCountdown = () => {
    setIsAnalyzing(true);
    setCoachInsight(null);
    setCountdown(5); 
  };

  const performCaptureAndAnalysis = async () => {
    setShowFlash(true);
    setTimeout(() => setShowFlash(false), 200);

    if (!webcamRef.current) return;

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            setCoachInsight("Camera unavailable.");
            setIsAnalyzing(false);
            return;
        }

        const base64Data = imageSrc.split(',')[1];
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
                    { text: `Analyze this ${currentExercise} form in one short sentence. Is the posture correct?` }
                ]
            }
        });
        setCoachInsight(response.text || "Analysis result unavailable.");

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    // Save the final active exercise stats
    const currentValue = currentExercise === 'Plank' ? holdTimer : repCount;
    const finalStats = { ...accumulatedStats.current };

    if (currentValue > 0) {
        finalStats[currentExercise] = (finalStats[currentExercise] || 0) + currentValue;
    }

    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    // Calculate total reps for legacy field
    const totalReps = Object.entries(finalStats).reduce((acc, [name, val]) => {
        return name === 'Plank' ? acc : acc + val;
    }, 0);

    onSave({
        durationSeconds,
        exercises: Object.keys(finalStats),
        exerciseStats: finalStats, // Pass the detailed map
        painLevel: 2, 
        accuracyScore: accuracy,
        reps: totalReps, 
        averageAngle: Math.round(angleSumRef.current / (angleFrameCountRef.current || 1))
    });
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-[100dvh]">

      {/* 1. Header Bar */}
      <div className="shrink-0 z-20 p-4 flex justify-between items-center bg-white/95 backdrop-blur-sm border-b border-gray-100">
         <div className="flex items-center gap-4 flex-1">
             <select 
                value={currentExercise}
                onChange={(e) => switchExercise(e.target.value)}
                className="bg-white text-[#778873] border border-gray-200 rounded-xl px-4 py-2 text-sm font-bold uppercase tracking-wider focus:outline-none focus:ring-2 focus:ring-[#778873]/50 focus:border-[#778873] cursor-pointer appearance-none shadow-sm transition-all hover:border-[#778873]"
             >
                {EXERCISE_OPTIONS.map(ex => (
                    <option key={ex} value={ex}>{ex}</option>
                ))}
             </select>

             <div className="w-px h-6 bg-gray-200"></div>

             {currentExercise === 'Plank' ? (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{formatTime(holdTimer)}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Hold Time</span>
                </div>
             ) : (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{repCount}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Reps</span>
                </div>
             )}
         </div>
         <button 
            onClick={onExit}
            className="text-slate-400 p-2 bg-gray-50 rounded-full hover:bg-gray-100 hover:text-gray-900 transition-colors"
         >
             <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
         </button>
      </div>

      {/* 2. Main Vision Area */}
      <div className="relative flex-1 bg-gray-50 overflow-hidden flex flex-col justify-center items-center p-4">
         <div className="relative w-full h-full max-w-5xl max-h-full flex items-center justify-center bg-white rounded-3xl shadow-sm border border-gray-200 overflow-hidden aspect-video md:aspect-auto">
             <Webcam
                ref={webcamRef}
                audio={false}
                screenshotFormat="image/jpeg"
                className="absolute w-full h-full object-cover md:object-contain"
                videoConstraints={{ facingMode: "user" }}
            />
            <canvas 
                ref={canvasRef} 
                className="absolute w-full h-full object-cover md:object-contain pointer-events-none"
            />

            {showFlash && (
                <div className="absolute inset-0 bg-white z-50 animate-pulse pointer-events-none"></div>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-40 backdrop-blur-sm">
                    <div className="text-center text-white">
                        <p className="text-8xl font-bold font-display animate-ping">{countdown}</p>
                        <p className="text-xl font-medium mt-4 uppercase tracking-widest">Get into position!</p>
                    </div>
                </div>
            )}
         </div>

         {/* Phase Indicator */}
         <div className="absolute bottom-8 left-0 right-0 flex justify-center pointer-events-none z-20">
             <div className="bg-white/90 backdrop-blur px-4 py-1 rounded-full border border-gray-200 shadow-sm">
                 <span className={`font-bold text-xs uppercase tracking-widest ${exerciseState === 'ACTIVE' ? 'text-[#778873]' : 'text-slate-400'}`}>
                    {exerciseState === 'ACTIVE' ? 'Active Phase' : 'Start Phase'}
                 </span>
             </div>
         </div>

         {/* Live Feedback Toast */}
         {isBadForm && feedbackMessage && (
          <div className="absolute top-8 left-4 right-4 flex justify-center z-30 pointer-events-none animate-bounce">
             <div className="bg-red-600 text-white px-6 py-3 rounded-xl shadow-xl flex items-center gap-3 max-w-md text-center border border-red-700">
                <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                <span className="font-bold text-sm tracking-wide">{feedbackMessage}</span>
             </div>
          </div>
         )}

         {/* Metric Display */}
         <div className="absolute top-8 left-8 z-20 hidden md:block">
             <div className={`
                 backdrop-blur-md p-5 rounded-3xl border shadow-lg transition-all duration-300 min-w-[120px]
                 ${isBadForm ? 'bg-red-50/90 border-red-200' : 'bg-white/90 border-gray-200'}
             `}>
                 <span className={`text-xs font-bold uppercase block mb-1 tracking-wider ${isBadForm ? 'text-red-700' : 'text-slate-500'}`}>
                    {metricLabel}
                 </span>
                 <div className="flex items-center gap-2">
                     <span className={`text-5xl font-bold tracking-tighter ${isBadForm ? 'text-red-600' : 'text-gray-900'}`}>
                         {displayMetric}°
                     </span>
                 </div>
             </div>
         </div>

         {/* Coach Insight */}
         {coachInsight && (
           <div className="absolute top-24 left-4 right-4 flex justify-center z-40 pointer-events-none">
             <div className="bg-white/95 backdrop-blur-md p-4 rounded-2xl shadow-xl border border-gray-200 pointer-events-auto max-w-lg flex items-start gap-4 animate-fade-in-down">
                <div className="p-2.5 bg-[#778873] rounded-xl text-white shrink-0 shadow-sm">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                </div>
                <div className="flex-1">
                    <p className="text-[#778873] font-bold text-xs uppercase tracking-wider mb-1">AI Coach Insight</p>
                    <p className="text-gray-800 text-sm leading-relaxed">
                        {coachInsight}
                    </p>
                </div>
                 <button 
                    onClick={() => setCoachInsight(null)}
                    className="text-slate-400 hover:text-gray-900"
                 >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                 </button>
             </div>
           </div>
         )}

         {!window.Pose && (
             <div className="absolute inset-0 flex items-center justify-center bg-white z-30">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#778873] mx-auto mb-4"></div>
                    <p className="text-gray-900 font-medium">Initializing Vision Engine...</p>
                </div>
             </div>
        )}
      </div>

      <div className="shrink-0 z-20 p-4 bg-white border-t border-gray-200">
          <div className="max-w-xl mx-auto flex flex-col md:flex-row gap-3">
               <Button 
                   fullWidth 
                   onClick={startAnalysisCountdown}
                   disabled={isAnalyzing || countdown !== null}
                   variant="outline"
                   icon={isAnalyzing ? <div className="animate-spin h-5 w-5 border-2 border-[#778873] rounded-full border-t-transparent"/> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>}
               >
                   {countdown !== null ? `Capturing in ${countdown}...` : (isAnalyzing ? "Analyzing..." : "Analyze Posture")}
               </Button>

               <Button 
                   fullWidth 
                   variant="primary" 
                   onClick={handleFinish}
               >
                   End Session
               </Button>
          </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Dashboard } from './components/Dashboard';
import { SessionView } from './components/SessionView';
import { Header } from './components/Header';
import { ReportCard } from './components/ReportCard';
import { Session, ViewState } from './types';
import { GoogleGenAI } from "@google/genai";

function App() {
  const [view, setView] = useState<ViewState>(ViewState.DASHBOARD);
  // Local state for sessions instead of Firestore
  const [sessions, setSessions] = useState<Session[]>([]);
  // Temp state for report view
  const [currentSession, setCurrentSession] = useState<Session | null>(null);
  const [isGeneratingReport, setIsGeneratingReport] = useState(false);

  const handleStartSession = () => {
    setView(ViewState.SESSION);
  };

  const handleBackToDashboard = () => {
    setView(ViewState.DASHBOARD);
  }

  const handleSessionComplete = async (data: any) => {
    setIsGeneratingReport(true);
    let summary = "Session analysis unavailable.";

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        // Format exercise data for the prompt
        const exerciseText = Object.entries(data.exerciseStats || {})
            .map(([name, val]) => `${name}: ${val} ${name === 'Plank' ? 'seconds' : 'reps'}`)
            .join(', ');

        const prompt = `Act as a Physiotherapist. Analyze this patient data: 
            Exercises Performed: ${exerciseText}
            Duration: ${data.durationSeconds} seconds
            Form Accuracy: ${data.accuracyScore}%

            Write a 3-sentence clinical observation for their doctor, focusing on stability and consistency.`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
        });
        if (response.text) {
            summary = response.text;
        }
    } catch (e) {
        console.error("AI Generation failed", e);
        summary = "Session completed. Unable to generate clinical observation at this time.";
    }

    const newSession: Session = {
        id: Date.now().toString(),
        userId: 'local-user',
        timestamp: new Date(),
        durationSeconds: data.durationSeconds,
        exercises: data.exercises,
        exerciseStats: data.exerciseStats,
        painLevel: data.painLevel,
        accuracyScore: data.accuracyScore,
        reps: data.reps,
        averageAngle: data.averageAngle,
        aiSummary: summary
    };

    setCurrentSession(newSession);
    setView(ViewState.REPORT);
    setIsGeneratingReport(false);
  }

  const handleReportClose = () => {
    if (currentSession) {
        setSessions(prev => [currentSession, ...prev]);
        setCurrentSession(null);
    }
    setView(ViewState.DASHBOARD);
  };

  return (
    <div className="min-h-screen bg-white font-sans selection:bg-[#778873] selection:text-white text-gray-900">
      {view === ViewState.DASHBOARD && (
        <Header />
      )}

      <main>
        {view === ViewState.DASHBOARD && (
          <Dashboard sessions={sessions} onStartSession={handleStartSession} />
        )}

        {view === ViewState.SESSION && (
            <>
            {isGeneratingReport ? (
                <div className="fixed inset-0 bg-white/95 flex flex-col items-center justify-center z-[60] backdrop-blur-sm">
                    <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-[#778873] mb-6"></div>
                    <h2 className="text-2xl font-bold text-gray-900 font-display">Generating Clinical Report...</h2>
                    <p className="text-slate-500 mt-2">Dr. AI is analyzing your biomechanics.</p>
                </div>
            ) : (
                <SessionView 
                    onExit={handleBackToDashboard}
                    onSave={handleSessionComplete}
                />
            )}
            </>
        )}

        {view === ViewState.REPORT && currentSession && (
            <ReportCard 
                session={currentSession}
                onClose={handleReportClose}
            />
        )}
      </main>
    </div>
  );
}

export default App;

import React from 'react';
import { Session } from '../types';
import { Button } from './Button';

interface ReportCardProps {
  session: Session;
  onClose: () => void;
}

export const ReportCard: React.FC<ReportCardProps> = ({ session, onClose }) => {
  const dateStr = session.timestamp.toLocaleDateString();
  const timeStr = session.timestamp.toLocaleTimeString();

  const handleDownloadPDF = () => {
    if (!window.jspdf) {
        console.error("jsPDF not loaded");
        return;
    }

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    // Header
    doc.setFontSize(20);
    doc.setTextColor(119, 136, 115); // Sage Color
    doc.text("Kinexa - Physical Therapy Session", 14, 22);

    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.text(`Date: ${dateStr} at ${timeStr}`, 14, 30);
    doc.text(`Patient ID: Local User`, 14, 35);

    // Table Data
    const tableData = Object.entries(session.exerciseStats || {})
      .filter(([_, val]) => val > 0)
      .map(([name, val]) => [
        name, 
        name === 'Plank' ? `${val} seconds` : `${val} reps`, 
        "Completed"
      ]);

    if (tableData.length === 0) {
        tableData.push(["No exercises performed", "-", "-"]);
    }

    // AutoTable
    doc.autoTable({
        startY: 45,
        head: [['Exercise Name', 'Result', 'Notes']],
        body: tableData,
        headStyles: { fillColor: [119, 136, 115] },
        styles: { font: "helvetica" }
    });

    // AI Insight
    const finalY = (doc as any).lastAutoTable.finalY || 60;

    doc.setFontSize(12);
    doc.setTextColor(0);
    doc.text("Clinical Notes", 14, finalY + 15);

    doc.setFontSize(10);
    doc.setTextColor(80);
    const splitText = doc.splitTextToSize(session.aiSummary, 180);
    doc.text(splitText, 14, finalY + 22);

    doc.save(`kinexa-report-${session.timestamp.getTime()}.pdf`);
  };

  return (
    <div className="min-h-screen bg-white flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden border border-gray-200">
        {/* Header */}
        <div className="bg-[#778873] p-8 text-white">
          <div className="flex justify-between items-center mb-2">
            <h2 className="text-2xl font-bold font-display tracking-wide">Session Report Card</h2>
            <div className="p-2 bg-white/10 rounded-lg">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
            </div>
          </div>
          <p className="opacity-90">{dateStr} • {timeStr}</p>
        </div>

        {/* Content */}
        <div className="p-8 space-y-8">

          {/* Detailed Exercise Grid */}
          <div>
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4">Exercises Performed</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {Object.entries(session.exerciseStats || {}).length > 0 ? (
                    Object.entries(session.exerciseStats)
                    .filter(([_, val]) => val > 0)
                    .map(([name, val]) => (
                        <div key={name} className="bg-white p-4 rounded-xl border border-gray-200 flex justify-between items-center shadow-sm">
                            <span className="font-bold text-gray-900">{name}</span>
                            <span className="text-[#778873] font-bold bg-green-50 px-3 py-1 rounded-lg">
                                {name === 'Plank' ? `${val}s` : `${val} reps`}
                            </span>
                        </div>
                    ))
                ) : (
                    <p className="text-slate-500 text-sm">No exercises recorded.</p>
                )}
            </div>
          </div>

          {/* AI Summary */}
          <div className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm ring-1 ring-[#778873]/5">
             <h3 className="text-[#778873] font-bold text-sm uppercase tracking-wider mb-3 flex items-center gap-2">
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>
                Clinical Observation
             </h3>
             <p className="text-gray-800 leading-relaxed italic text-lg">
                "{session.aiSummary}"
             </p>
          </div>

          <div className="flex gap-4">
             <div className="flex-1 bg-gray-50 p-3 rounded-xl border border-gray-100 text-center">
                <p className="text-xs text-slate-500 uppercase font-bold">Accuracy</p>
                <p className="text-xl font-bold text-gray-900">{session.accuracyScore}%</p>
             </div>
             <div className="flex-1 bg-gray-50 p-3 rounded-xl border border-gray-100 text-center">
                <p className="text-xs text-slate-500 uppercase font-bold">Total Time</p>
                <p className="text-xl font-bold text-gray-900">{Math.floor(session.durationSeconds / 60)}m {session.durationSeconds % 60}s</p>
             </div>
          </div>

          {/* Actions */}
          <div className="flex flex-col sm:flex-row gap-4 pt-4 border-t border-gray-100">
            <Button 
                onClick={handleDownloadPDF}
                variant="primary" 
                fullWidth
                icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>}
            >
                Download PDF Report
            </Button>
            <Button 
                onClick={onClose}
                variant="outline"
                fullWidth
            >
                Close & Save
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

import { 
  signInWithPopup, 
  signOut, 
  onAuthStateChanged, 
  User 
} from 'firebase/auth';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  orderBy, 
  addDoc,
  Timestamp 
} from 'firebase/firestore';
import { auth, googleProvider, db } from '../firebaseConfig';
import { Session, UserProfile } from '../types';

// --- Authentication ---

export const loginWithGoogle = async (): Promise<UserProfile> => {
  try {
    const result = await signInWithPopup(auth, googleProvider);
    const user = result.user;
    return {
      uid: user.uid,
      displayName: user.displayName,
      email: user.email,
      photoURL: user.photoURL,
    };
  } catch (error: any) {
    console.error("Error logging in with Google", error);

    // FIX: Handle unauthorized domain error (common in preview environments)
    // If the domain is not whitelisted in Firebase Console, fallback to a demo user
    // so the application remains testable.
    if (
      error.code === 'auth/unauthorized-domain' || 
      error.code === 'auth/configuration-not-found' ||
      error.code === 'auth/operation-not-allowed'
    ) {
      console.warn("Environment domain not authorized. Falling back to Demo Mode.");
      return {
        uid: 'demo-user-fallback',
        displayName: 'Demo Patient',
        email: 'demo@kineticrehab.app',
        photoURL: null
      };
    }

    throw error;
  }
};

export const logoutUser = async (): Promise<void> => {
  try {
    await signOut(auth);
  } catch (error) {
    console.error("Error signing out", error);
    // If we were in demo mode, signOut might fail or do nothing, which is fine.
  }
};

export const subscribeToAuthChanges = (callback: (user: UserProfile | null) => void) => {
  return onAuthStateChanged(auth, (user: User | null) => {
    if (user) {
      callback({
        uid: user.uid,
        displayName: user.displayName,
        email: user.email,
        photoURL: user.photoURL,
      });
    } else {
      callback(null);
    }
  });
};

// --- Firestore ---

export const getUserSessions = async (userId: string): Promise<Session[]> => {
  try {
    // If we are in demo mode (fallback user), forcing an error here or checking ID
    // isn't strictly necessary as the query will likely fail due to permissions 
    // or invalid config, triggering the catch block below which returns mock data.

    if (userId === 'demo-user-fallback') {
       throw new Error("Demo mode: Fetching mock data");
    }

    const sessionsRef = collection(db, 'sessions');
    const q = query(
      sessionsRef, 
      where('userId', '==', userId),
      orderBy('timestamp', 'desc')
    );

    const querySnapshot = await getDocs(q);

    return querySnapshot.docs.map(doc => {
      const data = doc.data();
      return {
        id: doc.id,
        userId: data.userId,
        timestamp: (data.timestamp as Timestamp).toDate(),
        durationSeconds: data.durationSeconds,
        exercises: data.exercises,
        exerciseStats: data.exerciseStats || {},
        painLevel: data.painLevel,
        accuracyScore: data.accuracyScore,
        reps: data.reps,
        averageAngle: data.averageAngle,
        aiSummary: data.aiSummary,
      } as Session;
    });
  } catch (error) {
    console.warn("Firestore fetch failed or Demo Mode active. Returning mock data.");
    // Return mock data if Firestore fails (for demo purposes)
    return [
      {
        id: '1',
        userId: userId,
        timestamp: new Date(Date.now() - 86400000 * 1), // 1 day ago
        durationSeconds: 1240,
        exercises: ['Squats', 'Lunges'],
        exerciseStats: { 'Squats': 30, 'Lunges': 20 },
        painLevel: 3,
        accuracyScore: 85,
        aiSummary: 'Great stability on the left knee. Slight valgus observed during deep squats. Recommended focusing on glute medius activation.'
      },
      {
        id: '2',
        userId: userId,
        timestamp: new Date(Date.now() - 86400000 * 3), // 3 days ago
        durationSeconds: 900,
        exercises: ['Hip Bridges', 'Clamshells'],
        exerciseStats: { 'Hip Bridges': 15, 'Clamshells': 20 },
        painLevel: 5,
        accuracyScore: 72,
        aiSummary: 'Movement was consistent but range of motion was limited due to reported pain. Good adherence to tempo.'
      },
      {
        id: '3',
        userId: userId,
        timestamp: new Date(Date.now() - 86400000 * 7), // 7 days ago
        durationSeconds: 1500,
        exercises: ['Squats', 'Planks'],
        exerciseStats: { 'Squats': 40, 'Planks': 120 },
        painLevel: 2,
        accuracyScore: 91,
        aiSummary: 'Excellent form today. Your knee alignment has improved by 10% since last week.'
      }
    ];
  }
};

export const saveSession = async (session: Omit<Session, 'id'>): Promise<string> => {
  try {
    if (session.userId === 'demo-user-fallback') {
        // Simulate network delay
        await new Promise(resolve => setTimeout(resolve, 800));
        return "mock-session-id-" + Date.now();
    }

    const docRef = await addDoc(collection(db, 'sessions'), {
      ...session,
      timestamp: Timestamp.fromDate(session.timestamp)
    });
    return docRef.id;
  } catch (error) {
    console.error("Error saving session", error);
    // Return a mock ID for demo continuity
    return "mock-session-id-" + Date.now();
  }
};

import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

const EXERCISE_OPTIONS = [
  'Squats',
  'Pushups',
  'Lateral Lunge',
  'Plank',
];

// --- 4. Threshold Dictionary ---
const EXERCISE_RULES = {
  Squats: {
    type: 'REP',
    metric: 'Angle',
    front: { start: 165, active: 130 },
    lateral: { start: 160, active: 100 }, 
  },
  Pushups: {
    type: 'REP',
    metric: 'Elbow Angle',
    lateral: { start: 160, active: 90 },
    front: { start: 160, active: 90 },
  },
  'Lateral Lunge': {
    type: 'REP',
    metric: 'Working Knee',
    startAngle: 165,    
    workingMax: 110,    
    staticMin: 150,     
    hipDropThreshold: 0.1 
  },
  Plank: {
    type: 'DURATION',
    metric: 'Body Alignment',
    minAngle: 165,
    maxAngle: 195,
  }
};

type ExerciseState = 'START' | 'ACTIVE';

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [currentExercise, setCurrentExercise] = useState('Squats');
  const [repCount, setRepCount] = useState(0);
  const [displayMetric, setDisplayMetric] = useState<number>(0); 
  const [metricLabel, setMetricLabel] = useState('Angle');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');
  const [isBadForm, setIsBadForm] = useState(false);

  // Session Accumulation State
  const accumulatedStats = useRef<Record<string, number>>({});

  // State Machine Indicators
  const [exerciseState, setExerciseState] = useState<ExerciseState>('START');
  const [holdTimer, setHoldTimer] = useState(0);

  // Analysis & Countdown State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [showFlash, setShowFlash] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });
  const angleSumRef = useRef(0);
  const angleFrameCountRef = useRef(0);

  // Tracking Refs
  const stateRef = useRef<ExerciseState>('START');
  const lastRepTimeRef = useRef<number>(0);
  const activeStartTimeRef = useRef<number>(0);
  const lastTimerTickRef = useRef<number>(0);
  const standingHipYRef = useRef<number>(0);

  // --- Helpers ---
  const calculateAngle = (a: any, b: any, c: any) => {
    if (!a || !b || !c) return 180;
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);
    if (angle > 180.0) angle = 360 - angle;
    return Math.round(angle);
  };

  const getDominantSide = (landmarks: any[]) => {
    const leftVis = landmarks[11].visibility + landmarks[23].visibility + landmarks[25].visibility;
    const rightVis = landmarks[12].visibility + landmarks[24].visibility + landmarks[26].visibility;
    return leftVis > rightVis ? 'LEFT' : 'RIGHT';
  };

  const checkPlankForm = (shoulder: any, hip: any, knee: any) => {
    const angle = calculateAngle(shoulder, hip, knee);
    const rules = EXERCISE_RULES.Plank;
    return angle >= rules.minAngle && angle <= rules.maxAngle;
  };

  // --- Logic to Switch Exercise & Save Stats ---
  const switchExercise = (newExercise: string) => {
    // 1. Save current stats before switching
    const currentValue = currentExercise === 'Plank' ? holdTimer : repCount;
    if (currentValue > 0) {
      accumulatedStats.current[currentExercise] = (accumulatedStats.current[currentExercise] || 0) + currentValue;
    }

    // 2. Switch
    setCurrentExercise(newExercise);
  };

  useEffect(() => {
    // Reset Counters on exercise change
    setRepCount(0);
    setHoldTimer(0);
    setFeedbackMessage('');
    setIsBadForm(false);
    stateRef.current = 'START';
    setExerciseState('START');
    // Note: We do NOT reset accumulatedStats here

    // Reset tracking refs specific to exercise mechanics
    standingHipYRef.current = 0;
  }, [currentExercise]);

  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (countdown !== null && countdown > 0) {
      timer = setTimeout(() => setCountdown(c => (c !== null ? c - 1 : null)), 1000);
    } else if (countdown === 0) {
      setCountdown(null);
      performCaptureAndAnalysis();
    }
    return () => clearTimeout(timer);
  }, [countdown]);

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;
      if (!results.poseLandmarks) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      const lm = results.poseLandmarks;

      const side = getDominantSide(lm);
      const isLeft = side === 'LEFT';

      const shoulder = isLeft ? lm[11] : lm[12];
      const hip = isLeft ? lm[23] : lm[24];
      const knee = isLeft ? lm[25] : lm[26];
      const ankle = isLeft ? lm[27] : lm[28];
      const elbow = isLeft ? lm[13] : lm[14];
      const wrist = isLeft ? lm[15] : lm[16];

      const shoulderWidth = Math.abs(lm[11].x - lm[12].x);
      const isLateral = shoulderWidth < 0.15; 

      let currentMetric = 0;
      let formError = '';
      let isFormGood = true;

      switch(currentExercise) {
        case 'Squats': {
            const rules = EXERCISE_RULES.Squats;
            if (isLateral) {
                setMetricLabel('Hip Angle');
                currentMetric = calculateAngle(shoulder, hip, knee);
            } else {
                setMetricLabel('Knee Angle');
                currentMetric = calculateAngle(hip, knee, ankle);
            }
            setDisplayMetric(currentMetric);

            const thresholds = isLateral ? rules.lateral : rules.front;

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    const durationInActive = now - activeStartTimeRef.current;
                    const timeSinceLastRep = now - lastRepTimeRef.current;

                    if (durationInActive > 200 && timeSinceLastRep > 1000) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }

            if (!isLateral) {
                const hipSep = Math.abs(lm[23].x - lm[24].x);
                const kneeSep = Math.abs(lm[25].x - lm[26].x);
                if (kneeSep < hipSep * 0.7) {
                    formError = "Push knees outward";
                    isFormGood = false;
                }
            }
            break;
        }

        case 'Pushups': {
            setMetricLabel('Elbow Angle');
            currentMetric = calculateAngle(shoulder, elbow, wrist);
            setDisplayMetric(currentMetric);

            const rules = EXERCISE_RULES.Pushups;
            const thresholds = rules.lateral;

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    if ((now - activeStartTimeRef.current > 200) && (now - lastRepTimeRef.current > 1000)) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }

        case 'Lateral Lunge': {
            setMetricLabel('Working Knee');
            const rules = EXERCISE_RULES['Lateral Lunge'];

            const lKneeAngle = calculateAngle(lm[23], lm[25], lm[27]);
            const rKneeAngle = calculateAngle(lm[24], lm[26], lm[28]);
            const currentHipY = (lm[23].y + lm[24].y) / 2;
            const workingKneeAngle = Math.min(lKneeAngle, rKneeAngle);
            const staticKneeAngle = Math.max(lKneeAngle, rKneeAngle);

            currentMetric = workingKneeAngle;
            setDisplayMetric(currentMetric);

            if (stateRef.current === 'START') {
                if (lKneeAngle > rules.startAngle && rKneeAngle > rules.startAngle) {
                    if (standingHipYRef.current === 0 || currentHipY < standingHipYRef.current) {
                        standingHipYRef.current = currentHipY;
                    }
                }
                const hipDrop = currentHipY - standingHipYRef.current; 

                if (workingKneeAngle < rules.workingMax && 
                    staticKneeAngle > rules.staticMin &&
                    hipDrop > rules.hipDropThreshold) {
                        stateRef.current = 'ACTIVE';
                        setExerciseState('ACTIVE');
                        activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (lKneeAngle > rules.startAngle && rKneeAngle > rules.startAngle) {
                     const now = Date.now();
                     const durationInActive = now - activeStartTimeRef.current;
                     const timeSinceLastRep = now - lastRepTimeRef.current;

                     if (durationInActive > 300 && timeSinceLastRep > 1000) {
                         setRepCount(c => c + 1);
                         lastRepTimeRef.current = now;
                     }
                     stateRef.current = 'START';
                     setExerciseState('START');
                }
            }
            break;
        }

        case 'Plank': {
            setMetricLabel('Align Angle');
            const alignmentAngle = calculateAngle(shoulder, hip, knee);
            currentMetric = alignmentAngle;
            setDisplayMetric(currentMetric);

            const isAligned = checkPlankForm(shoulder, hip, knee);

            if (isAligned) {
                const now = Date.now();
                if (now - lastTimerTickRef.current >= 1000) {
                    setHoldTimer(t => t + 1);
                    lastTimerTickRef.current = now;
                }
                if (stateRef.current !== 'ACTIVE') {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                }
            } else {
                formError = "Align Hips to Resume";
                isFormGood = false;
                if (stateRef.current !== 'START') {
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }
      }

      if (currentExercise === 'Squats' && currentMetric > 0) {
        angleSumRef.current += currentMetric;
        angleFrameCountRef.current += 1;
      }
      statsRef.current.totalFrames++;
      if (isFormGood) statsRef.current.goodFrames++;

      setIsBadForm(!isFormGood);
      setFeedbackMessage(formError);

      // --- ADAPTIVE VISUALIZATION LOGIC ---

      const skeletonColor = !isFormGood ? '#EF4444' : '#778873'; // Red or Sage
      const landmarkColor = !isFormGood ? '#EF4444' : '#F1F3E0'; // Red or Cream

      if (!isLateral) {
         // --- Mode A: Full Frontal (Draw EVERYTHING) ---
         // When user faces camera, show full body map for high-tech feel
         window.drawConnectors(canvasCtx, lm, window.POSE_CONNECTIONS,
             { color: skeletonColor, lineWidth: 4 });

         window.drawLandmarks(canvasCtx, lm,
             { color: landmarkColor, lineWidth: 2, radius: 4 });
      } else {
         // --- Mode B: Lateral Precision (Draw VISIBLE SIDE only) ---
         // Reduces visual noise to focus on alignment

         // Define connections for specific sides [start, end]
         // Ear(7/8) -> Shoulder(11/12) -> Hip(23/24) -> Knee(25/26) -> Ankle(27/28)
         // Shoulder -> Elbow(13/14) -> Wrist(15/16)
         const lateralConnections = isLeft 
            ? [[7, 11], [11, 23], [23, 25], [25, 27], [11, 13], [13, 15]] // Left side
            : [[8, 12], [12, 24], [24, 26], [26, 28], [12, 14], [14, 16]]; // Right side

         // Filter landmarks to only draw the visible ones
         const visibleIndices = isLeft 
            ? [7, 11, 13, 15, 23, 25, 27] 
            : [8, 12, 14, 16, 24, 26, 28];

         const visibleLandmarks = visibleIndices.map(idx => lm[idx]);

         window.drawConnectors(canvasCtx, lm, lateralConnections,
             { color: skeletonColor, lineWidth: 4 });

         window.drawLandmarks(canvasCtx, visibleLandmarks,
             { color: landmarkColor, lineWidth: 4, radius: 6 });
      }

      canvasCtx.restore();
    };

    const initializePose = async () => {
        if (window.Pose) {
            pose = new window.Pose({
                locateFile: (file: string) => {
                    return `https://cdn.jsdelivr.net/npm/@mediapipe/pose@0.5.1675469404/${file}`;
                }
            });

            pose.setOptions({
                modelComplexity: 1,
                smoothLandmarks: true,
                enableSegmentation: false,
                minDetectionConfidence: 0.5,
                minTrackingConfidence: 0.5
            });

            pose.onResults(onResults);
            if (pose.initialize) await pose.initialize();
            detect();
        }
    };

    const detect = async () => {
      if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4 && pose) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    initializePose();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, [currentExercise]);

  const startAnalysisCountdown = () => {
    setIsAnalyzing(true);
    setCoachInsight(null);
    setCountdown(5); 
  };

  const performCaptureAndAnalysis = async () => {
    setShowFlash(true);
    setTimeout(() => setShowFlash(false), 200);

    if (!webcamRef.current) return;

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            setCoachInsight("Camera unavailable.");
            setIsAnalyzing(false);
            return;
        }

        const base64Data = imageSrc.split(',')[1];
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
                    { text: `Analyze this ${currentExercise} form in one short sentence. Is the posture correct?` }
                ]
            }
        });
        setCoachInsight(response.text || "Analysis result unavailable.");

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    // Save the final active exercise stats
    const currentValue = currentExercise === 'Plank' ? holdTimer : repCount;
    const finalStats = { ...accumulatedStats.current };

    if (currentValue > 0) {
        finalStats[currentExercise] = (finalStats[currentExercise] || 0) + currentValue;
    }

    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    // Calculate total reps for legacy field
    const totalReps = Object.entries(finalStats).reduce((acc, [name, val]) => {
        return name === 'Plank' ? acc : acc + val;
    }, 0);

    onSave({
        durationSeconds,
        exercises: Object.keys(finalStats),
        exerciseStats: finalStats, // Pass the detailed map
        painLevel: 2, 
        accuracyScore: accuracy,
        reps: totalReps, 
        averageAngle: Math.round(angleSumRef.current / (angleFrameCountRef.current || 1))
    });
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-[100dvh]">

      {/* 1. Header Bar */}
      <div className="shrink-0 z-20 p-4 flex justify-between items-center bg-white/95 backdrop-blur-sm border-b border-gray-100">
         <div className="flex items-center gap-4 flex-1">
             <select 
                value={currentExercise}
                onChange={(e) => switchExercise(e.target.value)}
                className="bg-white text-[#778873] border border-gray-200 rounded-xl px-4 py-2 text-sm font-bold uppercase tracking-wider focus:outline-none focus:ring-2 focus:ring-[#778873]/50 focus:border-[#778873] cursor-pointer appearance-none shadow-sm transition-all hover:border-[#778873]"
             >
                {EXERCISE_OPTIONS.map(ex => (
                    <option key={ex} value={ex}>{ex}</option>
                ))}
             </select>

             <div className="w-px h-6 bg-gray-200"></div>

             {currentExercise === 'Plank' ? (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{formatTime(holdTimer)}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Hold Time</span>
                </div>
             ) : (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{repCount}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Reps</span>
                </div>
             )}
         </div>
         <button 
            onClick={onExit}
            className="text-slate-400 p-2 bg-gray-50 rounded-full hover:bg-gray-100 hover:text-gray-900 transition-colors"
         >
             <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
         </button>
      </div>

      {/* 2. Main Vision Area */}
      <div className="relative flex-1 bg-gray-50 overflow-hidden flex flex-col justify-center items-center p-4">
         <div className="relative w-full h-full max-w-5xl max-h-full flex items-center justify-center bg-white rounded-3xl shadow-sm border border-gray-200 overflow-hidden aspect-video md:aspect-auto">
             <Webcam
                ref={webcamRef}
                audio={false}
                screenshotFormat="image/jpeg"
                className="absolute w-full h-full object-cover md:object-contain"
                videoConstraints={{ facingMode: "user" }}
            />
            <canvas 
                ref={canvasRef} 
                className="absolute w-full h-full object-cover md:object-contain pointer-events-none"
            />

            {showFlash && (
                <div className="absolute inset-0 bg-white z-50 animate-pulse pointer-events-none"></div>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-40 backdrop-blur-sm">
                    <div className="text-center text-white">
                        <p className="text-8xl font-bold font-display animate-ping">{countdown}</p>
                        <p className="text-xl font-medium mt-4 uppercase tracking-widest">Get into position!</p>
                    </div>
                </div>
            )}
         </div>

         {/* Phase Indicator */}
         <div className="absolute bottom-8 left-0 right-0 flex justify-center pointer-events-none z-20">
             <div className="bg-white/90 backdrop-blur px-4 py-1 rounded-full border border-gray-200 shadow-sm">
                 <span className={`font-bold text-xs uppercase tracking-widest ${exerciseState === 'ACTIVE' ? 'text-[#778873]' : 'text-slate-400'}`}>
                    {exerciseState === 'ACTIVE' ? 'Active Phase' : 'Start Phase'}
                 </span>
             </div>
         </div>

         {/* Live Feedback Toast */}
         {isBadForm && feedbackMessage && (
          <div className="absolute top-8 left-4 right-4 flex justify-center z-30 pointer-events-none animate-bounce">
             <div className="bg-red-600 text-white px-6 py-3 rounded-xl shadow-xl flex items-center gap-3 max-w-md text-center border border-red-700">
                <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                <span className="font-bold text-sm tracking-wide">{feedbackMessage}</span>
             </div>
          </div>
         )}

         {/* Metric Display */}
         <div className="absolute top-8 left-8 z-20 hidden md:block">
             <div className={`
                 backdrop-blur-md p-5 rounded-3xl border shadow-lg transition-all duration-300 min-w-[120px]
                 ${isBadForm ? 'bg-red-50/90 border-red-200' : 'bg-white/90 border-gray-200'}
             `}>
                 <span className={`text-xs font-bold uppercase block mb-1 tracking-wider ${isBadForm ? 'text-red-700' : 'text-slate-500'}`}>
                    {metricLabel}
                 </span>
                 <div className="flex items-center gap-2">
                     <span className={`text-5xl font-bold tracking-tighter ${isBadForm ? 'text-red-600' : 'text-gray-900'}`}>
                         {displayMetric}°
                     </span>
                 </div>
             </div>
         </div>

         {/* Coach Insight */}
         {coachInsight && (
           <div className="absolute top-24 left-4 right-4 flex justify-center z-40 pointer-events-none">
             <div className="bg-white/95 backdrop-blur-md p-4 rounded-2xl shadow-xl border border-gray-200 pointer-events-auto max-w-lg flex items-start gap-4 animate-fade-in-down">
                <div className="p-2.5 bg-[#778873] rounded-xl text-white shrink-0 shadow-sm">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                </div>
                <div className="flex-1">
                    <p className="text-[#778873] font-bold text-xs uppercase tracking-wider mb-1">AI Coach Insight</p>
                    <p className="text-gray-800 text-sm leading-relaxed">
                        {coachInsight}
                    </p>
                </div>
                 <button 
                    onClick={() => setCoachInsight(null)}
                    className="text-slate-400 hover:text-gray-900"
                 >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                 </button>
             </div>
           </div>
         )}

         {!window.Pose && (
             <div className="absolute inset-0 flex items-center justify-center bg-white z-30">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#778873] mx-auto mb-4"></div>
                    <p className="text-gray-900 font-medium">Initializing Vision Engine...</p>
                </div>
             </div>
        )}
      </div>

      <div className="shrink-0 z-20 p-4 bg-white border-t border-gray-200">
          <div className="max-w-xl mx-auto flex flex-col md:flex-row gap-3">
               <Button 
                   fullWidth 
                   onClick={startAnalysisCountdown}
                   disabled={isAnalyzing || countdown !== null}
                   variant="outline"
                   icon={isAnalyzing ? <div className="animate-spin h-5 w-5 border-2 border-[#778873] rounded-full border-t-transparent"/> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>}
               >
                   {countdown !== null ? `Capturing in ${countdown}...` : (isAnalyzing ? "Analyzing..." : "Analyze Posture")}
               </Button>

               <Button 
                   fullWidth 
                   variant="primary" 
                   onClick={handleFinish}
               >
                   End Session
               </Button>
          </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import Webcam from 'react-webcam';
import { Button } from './Button';
import { GoogleGenAI } from "@google/genai";

interface SessionViewProps {
  onExit: () => void;
  onSave: (data: any) => void;
}

const EXERCISE_OPTIONS = [
  'Squats',
  'Pushups',
  'Lateral Lunge',
  'Plank',
];

// --- 4. Threshold Dictionary ---
const EXERCISE_RULES = {
  Squats: {
    type: 'REP',
    metric: 'Angle',
    front: { start: 165, active: 130 },
    lateral: { start: 160, active: 100 }, 
  },
  Pushups: {
    type: 'REP',
    metric: 'Elbow Angle',
    lateral: { start: 160, active: 90 },
    front: { start: 160, active: 90 },
  },
  'Lateral Lunge': {
    type: 'REP',
    metric: 'Working Knee',
    startAngle: 165,    
    workingMax: 110,    
    staticMin: 150,     
    hipDropThreshold: 0.1 
  },
  Plank: {
    type: 'DURATION',
    metric: 'Body Alignment',
    minAngle: 165,
    maxAngle: 195,
  }
};

type ExerciseState = 'START' | 'ACTIVE';

export const SessionView: React.FC<SessionViewProps> = ({ onExit, onSave }) => {
  const webcamRef = useRef<Webcam>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // UI State
  const [currentExercise, setCurrentExercise] = useState('Squats');
  const [repCount, setRepCount] = useState(0);
  const [displayMetric, setDisplayMetric] = useState<number>(0); 
  const [metricLabel, setMetricLabel] = useState('Angle');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('');
  const [isBadForm, setIsBadForm] = useState(false);

  // Session Accumulation State
  const accumulatedStats = useRef<Record<string, number>>({});

  // State Machine Indicators
  const [exerciseState, setExerciseState] = useState<ExerciseState>('START');
  const [holdTimer, setHoldTimer] = useState(0);

  // Analysis & Countdown State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [showFlash, setShowFlash] = useState(false);
  const [coachInsight, setCoachInsight] = useState<string | null>(null);

  // Logic Refs
  const startTimeRef = useRef<number>(Date.now());
  const requestRef = useRef<number | null>(null);
  const statsRef = useRef({ goodFrames: 0, totalFrames: 0 });
  const angleSumRef = useRef(0);
  const angleFrameCountRef = useRef(0);

  // Tracking Refs
  const stateRef = useRef<ExerciseState>('START');
  const lastRepTimeRef = useRef<number>(0);
  const activeStartTimeRef = useRef<number>(0);
  const lastTimerTickRef = useRef<number>(0);
  const standingHipYRef = useRef<number>(0);

  // --- Helpers ---
  const calculateAngle = (a: any, b: any, c: any) => {
    if (!a || !b || !c) return 180;
    const radians = Math.atan2(c.y - b.y, c.x - b.x) - Math.atan2(a.y - b.y, a.x - b.x);
    let angle = Math.abs(radians * 180.0 / Math.PI);
    if (angle > 180.0) angle = 360 - angle;
    return Math.round(angle);
  };

  const getDominantSide = (landmarks: any[]) => {
    const leftVis = landmarks[11].visibility + landmarks[23].visibility + landmarks[25].visibility;
    const rightVis = landmarks[12].visibility + landmarks[24].visibility + landmarks[26].visibility;
    return leftVis > rightVis ? 'LEFT' : 'RIGHT';
  };

  const checkPlankForm = (shoulder: any, hip: any, knee: any) => {
    const angle = calculateAngle(shoulder, hip, knee);
    const rules = EXERCISE_RULES.Plank;
    return angle >= rules.minAngle && angle <= rules.maxAngle;
  };

  // --- Logic to Switch Exercise & Save Stats ---
  const switchExercise = (newExercise: string) => {
    // 1. Save current stats before switching
    const currentValue = currentExercise === 'Plank' ? holdTimer : repCount;
    if (currentValue > 0) {
      accumulatedStats.current[currentExercise] = (accumulatedStats.current[currentExercise] || 0) + currentValue;
    }

    // 2. Switch
    setCurrentExercise(newExercise);
  };

  useEffect(() => {
    // Reset Counters on exercise change
    setRepCount(0);
    setHoldTimer(0);
    setFeedbackMessage('');
    setIsBadForm(false);
    stateRef.current = 'START';
    setExerciseState('START');
    // Note: We do NOT reset accumulatedStats here

    // Reset tracking refs specific to exercise mechanics
    standingHipYRef.current = 0;
  }, [currentExercise]);

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (countdown !== null && countdown > 0) {
      timer = setTimeout(() => setCountdown(c => (c !== null ? c - 1 : null)), 1000);
    } else if (countdown === 0) {
      setCountdown(null);
      performCaptureAndAnalysis();
    }
    return () => clearTimeout(timer);
  }, [countdown]);

  useEffect(() => {
    let pose: any = null;
    startTimeRef.current = Date.now();

    const onResults = (results: any) => {
      if (!canvasRef.current || !webcamRef.current?.video) return;
      if (!results.poseLandmarks) return;

      const videoWidth = webcamRef.current.video.videoWidth;
      const videoHeight = webcamRef.current.video.videoHeight;

      canvasRef.current.width = videoWidth;
      canvasRef.current.height = videoHeight;

      const canvasCtx = canvasRef.current.getContext('2d');
      if (!canvasCtx) return;

      canvasCtx.save();
      canvasCtx.clearRect(0, 0, videoWidth, videoHeight);

      const lm = results.poseLandmarks;

      const side = getDominantSide(lm);
      const isLeft = side === 'LEFT';

      const shoulder = isLeft ? lm[11] : lm[12];
      const hip = isLeft ? lm[23] : lm[24];
      const knee = isLeft ? lm[25] : lm[26];
      const ankle = isLeft ? lm[27] : lm[28];
      const elbow = isLeft ? lm[13] : lm[14];
      const wrist = isLeft ? lm[15] : lm[16];

      const shoulderWidth = Math.abs(lm[11].x - lm[12].x);
      const isLateral = shoulderWidth < 0.15; 

      let currentMetric = 0;
      let formError = '';
      let isFormGood = true;

      switch(currentExercise) {
        case 'Squats': {
            const rules = EXERCISE_RULES.Squats;
            if (isLateral) {
                setMetricLabel('Hip Angle');
                currentMetric = calculateAngle(shoulder, hip, knee);
            } else {
                setMetricLabel('Knee Angle');
                currentMetric = calculateAngle(hip, knee, ankle);
            }
            setDisplayMetric(currentMetric);

            const thresholds = isLateral ? rules.lateral : rules.front;

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    const durationInActive = now - activeStartTimeRef.current;
                    const timeSinceLastRep = now - lastRepTimeRef.current;

                    if (durationInActive > 200 && timeSinceLastRep > 1000) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }

            if (!isLateral) {
                const hipSep = Math.abs(lm[23].x - lm[24].x);
                const kneeSep = Math.abs(lm[25].x - lm[26].x);
                if (kneeSep < hipSep * 0.7) {
                    formError = "Push knees outward";
                    isFormGood = false;
                }
            }
            break;
        }

        case 'Pushups': {
            setMetricLabel('Elbow Angle');
            currentMetric = calculateAngle(shoulder, elbow, wrist);
            setDisplayMetric(currentMetric);

            const rules = EXERCISE_RULES.Pushups;
            const thresholds = rules.lateral;

            if (stateRef.current === 'START') {
                if (currentMetric <= thresholds.active) {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                    activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (currentMetric >= thresholds.start) {
                    const now = Date.now();
                    if ((now - activeStartTimeRef.current > 200) && (now - lastRepTimeRef.current > 1000)) {
                        setRepCount(c => c + 1);
                        lastRepTimeRef.current = now;
                    }
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }

        case 'Lateral Lunge': {
            setMetricLabel('Working Knee');
            const rules = EXERCISE_RULES['Lateral Lunge'];

            const lKneeAngle = calculateAngle(lm[23], lm[25], lm[27]);
            const rKneeAngle = calculateAngle(lm[24], lm[26], lm[28]);
            const currentHipY = (lm[23].y + lm[24].y) / 2;
            const workingKneeAngle = Math.min(lKneeAngle, rKneeAngle);
            const staticKneeAngle = Math.max(lKneeAngle, rKneeAngle);

            currentMetric = workingKneeAngle;
            setDisplayMetric(currentMetric);

            if (stateRef.current === 'START') {
                if (lKneeAngle > rules.startAngle && rKneeAngle > rules.startAngle) {
                    if (standingHipYRef.current === 0 || currentHipY < standingHipYRef.current) {
                        standingHipYRef.current = currentHipY;
                    }
                }
                const hipDrop = currentHipY - standingHipYRef.current; 

                if (workingKneeAngle < rules.workingMax && 
                    staticKneeAngle > rules.staticMin &&
                    hipDrop > rules.hipDropThreshold) {
                        stateRef.current = 'ACTIVE';
                        setExerciseState('ACTIVE');
                        activeStartTimeRef.current = Date.now();
                }
            } else if (stateRef.current === 'ACTIVE') {
                if (lKneeAngle > rules.startAngle && rKneeAngle > rules.startAngle) {
                     const now = Date.now();
                     const durationInActive = now - activeStartTimeRef.current;
                     const timeSinceLastRep = now - lastRepTimeRef.current;

                     if (durationInActive > 300 && timeSinceLastRep > 1000) {
                         setRepCount(c => c + 1);
                         lastRepTimeRef.current = now;
                     }
                     stateRef.current = 'START';
                     setExerciseState('START');
                }
            }
            break;
        }

        case 'Plank': {
            setMetricLabel('Align Angle');
            const alignmentAngle = calculateAngle(shoulder, hip, knee);
            currentMetric = alignmentAngle;
            setDisplayMetric(currentMetric);

            const isAligned = checkPlankForm(shoulder, hip, knee);

            if (isAligned) {
                const now = Date.now();
                if (now - lastTimerTickRef.current >= 1000) {
                    setHoldTimer(t => t + 1);
                    lastTimerTickRef.current = now;
                }
                if (stateRef.current !== 'ACTIVE') {
                    stateRef.current = 'ACTIVE';
                    setExerciseState('ACTIVE');
                }
            } else {
                formError = "Align Hips to Resume";
                isFormGood = false;
                if (stateRef.current !== 'START') {
                    stateRef.current = 'START';
                    setExerciseState('START');
                }
            }
            break;
        }
      }

      if (currentExercise === 'Squats' && currentMetric > 0) {
        angleSumRef.current += currentMetric;
        angleFrameCountRef.current += 1;
      }
      statsRef.current.totalFrames++;
      if (isFormGood) statsRef.current.goodFrames++;

      setIsBadForm(!isFormGood);
      setFeedbackMessage(formError);

      // --- ADAPTIVE VISUALIZATION LOGIC ---

      const skeletonColor = !isFormGood ? '#EF4444' : '#778873'; // Red or Sage
      const landmarkColor = !isFormGood ? '#EF4444' : '#F1F3E0'; // Red or Cream

      if (!isLateral) {
         // --- Mode A: Full Frontal (Draw EVERYTHING) ---
         // When user faces camera, show full body map for high-tech feel
         window.drawConnectors(canvasCtx, lm, window.POSE_CONNECTIONS,
             { color: skeletonColor, lineWidth: 4 });

         window.drawLandmarks(canvasCtx, lm,
             { color: landmarkColor, lineWidth: 2, radius: 4 });
      } else {
         // --- Mode B: Lateral Precision (Draw VISIBLE SIDE only) ---
         // Reduces visual noise to focus on alignment

         // Define connections for specific sides [start, end]
         // Ear(7/8) -> Shoulder(11/12) -> Hip(23/24) -> Knee(25/26) -> Ankle(27/28)
         // Shoulder -> Elbow(13/14) -> Wrist(15/16)
         const lateralConnections = isLeft 
            ? [[7, 11], [11, 23], [23, 25], [25, 27], [11, 13], [13, 15]] // Left side
            : [[8, 12], [12, 24], [24, 26], [26, 28], [12, 14], [14, 16]]; // Right side

         // Filter landmarks to only draw the visible ones
         const visibleIndices = isLeft 
            ? [7, 11, 13, 15, 23, 25, 27] 
            : [8, 12, 14, 16, 24, 26, 28];

         const visibleLandmarks = visibleIndices.map(idx => lm[idx]);

         window.drawConnectors(canvasCtx, lm, lateralConnections,
             { color: skeletonColor, lineWidth: 4 });

         window.drawLandmarks(canvasCtx, visibleLandmarks,
             { color: landmarkColor, lineWidth: 4, radius: 6 });
      }

      canvasCtx.restore();
    };

    const initializePose = async () => {
        if (window.Pose) {
            pose = new window.Pose({
                locateFile: (file: string) => {
                    return `https://cdn.jsdelivr.net/npm/@mediapipe/pose@0.5.1675469404/${file}`;
                }
            });

            pose.setOptions({
                modelComplexity: 1,
                smoothLandmarks: true,
                enableSegmentation: false,
                minDetectionConfidence: 0.5,
                minTrackingConfidence: 0.5
            });

            pose.onResults(onResults);
            if (pose.initialize) await pose.initialize();
            detect();
        }
    };

    const detect = async () => {
      if (webcamRef.current && webcamRef.current.video && webcamRef.current.video.readyState === 4 && pose) {
        await pose.send({ image: webcamRef.current.video });
      }
      requestRef.current = requestAnimationFrame(detect);
    };

    initializePose();

    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        if (pose) pose.close();
    };
  }, [currentExercise]);

  const startAnalysisCountdown = () => {
    setIsAnalyzing(true);
    setCoachInsight(null);
    setCountdown(5); 
  };

  const performCaptureAndAnalysis = async () => {
    setShowFlash(true);
    setTimeout(() => setShowFlash(false), 200);

    if (!webcamRef.current) return;

    try {
        const imageSrc = webcamRef.current.getScreenshot();
        if (!imageSrc) {
            setCoachInsight("Camera unavailable.");
            setIsAnalyzing(false);
            return;
        }

        const base64Data = imageSrc.split(',')[1];
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
                    { text: `Analyze this ${currentExercise} form in one short sentence. Is the posture correct?` }
                ]
            }
        });
        setCoachInsight(response.text || "Analysis result unavailable.");

    } catch (error) {
        console.error("Analysis failed", error);
        setCoachInsight("Could not analyze image. Please try again.");
    } finally {
        setIsAnalyzing(false);
    }
  };

  const handleFinish = () => {
    // Save the final active exercise stats
    const currentValue = currentExercise === 'Plank' ? holdTimer : repCount;
    const finalStats: Record<string, number> = { ...accumulatedStats.current };

    if (currentValue > 0) {
        finalStats[currentExercise] = (finalStats[currentExercise] || 0) + currentValue;
    }

    const durationSeconds = Math.floor((Date.now() - startTimeRef.current) / 1000);
    const accuracy = statsRef.current.totalFrames > 0 
        ? Math.round((statsRef.current.goodFrames / statsRef.current.totalFrames) * 100) 
        : 100;

    // Calculate total reps for legacy field
    const totalReps = Object.entries(finalStats).reduce((acc, [name, val]) => {
        return name === 'Plank' ? acc : acc + val;
    }, 0);

    onSave({
        durationSeconds,
        exercises: Object.keys(finalStats),
        exerciseStats: finalStats, // Pass the detailed map
        painLevel: 2, 
        accuracyScore: accuracy,
        reps: totalReps, 
        averageAngle: Math.round(angleSumRef.current / (angleFrameCountRef.current || 1))
    });
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-[100dvh]">

      {/* 1. Header Bar */}
      <div className="shrink-0 z-20 p-4 flex justify-between items-center bg-white/95 backdrop-blur-sm border-b border-gray-100">
         <div className="flex items-center gap-4 flex-1">
             <select 
                value={currentExercise}
                onChange={(e) => switchExercise(e.target.value)}
                className="bg-white text-[#778873] border border-gray-200 rounded-xl px-4 py-2 text-sm font-bold uppercase tracking-wider focus:outline-none focus:ring-2 focus:ring-[#778873]/50 focus:border-[#778873] cursor-pointer appearance-none shadow-sm transition-all hover:border-[#778873]"
             >
                {EXERCISE_OPTIONS.map(ex => (
                    <option key={ex} value={ex}>{ex}</option>
                ))}
             </select>

             <div className="w-px h-6 bg-gray-200"></div>

             {currentExercise === 'Plank' ? (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{formatTime(holdTimer)}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Hold Time</span>
                </div>
             ) : (
                <div className="flex items-baseline gap-1">
                    <span className="text-3xl font-bold text-[#778873] tabular-nums">{repCount}</span>
                    <span className="text-xs text-slate-500 font-medium uppercase tracking-wide">Reps</span>
                </div>
             )}
         </div>
         <button 
            onClick={onExit}
            className="text-slate-400 p-2 bg-gray-50 rounded-full hover:bg-gray-100 hover:text-gray-900 transition-colors"
         >
             <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
         </button>
      </div>

      {/* 2. Main Vision Area */}
      <div className="relative flex-1 bg-gray-50 overflow-hidden flex flex-col justify-center items-center p-4">
         <div className="relative w-full h-full max-w-5xl max-h-full flex items-center justify-center bg-white rounded-3xl shadow-sm border border-gray-200 overflow-hidden aspect-video md:aspect-auto">
             <Webcam
                ref={webcamRef}
                audio={false}
                screenshotFormat="image/jpeg"
                className="absolute w-full h-full object-cover md:object-contain"
                videoConstraints={{ facingMode: "user" }}
            />
            <canvas 
                ref={canvasRef} 
                className="absolute w-full h-full object-cover md:object-contain pointer-events-none"
            />

            {showFlash && (
                <div className="absolute inset-0 bg-white z-50 animate-pulse pointer-events-none"></div>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-40 backdrop-blur-sm">
                    <div className="text-center text-white">
                        <p className="text-8xl font-bold font-display animate-ping">{countdown}</p>
                        <p className="text-xl font-medium mt-4 uppercase tracking-widest">Get into position!</p>
                    </div>
                </div>
            )}
         </div>

         {/* Phase Indicator */}
         <div className="absolute bottom-8 left-0 right-0 flex justify-center pointer-events-none z-20">
             <div className="bg-white/90 backdrop-blur px-4 py-1 rounded-full border border-gray-200 shadow-sm">
                 <span className={`font-bold text-xs uppercase tracking-widest ${exerciseState === 'ACTIVE' ? 'text-[#778873]' : 'text-slate-400'}`}>
                    {exerciseState === 'ACTIVE' ? 'Active Phase' : 'Start Phase'}
                 </span>
             </div>
         </div>

         {/* Live Feedback Toast */}
         {isBadForm && feedbackMessage && (
          <div className="absolute top-8 left-4 right-4 flex justify-center z-30 pointer-events-none animate-bounce">
             <div className="bg-red-600 text-white px-6 py-3 rounded-xl shadow-xl flex items-center gap-3 max-w-md text-center border border-red-700">
                <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                <span className="font-bold text-sm tracking-wide">{feedbackMessage}</span>
             </div>
          </div>
         )}

         {/* Metric Display */}
         <div className="absolute top-8 left-8 z-20 hidden md:block">
             <div className={`
                 backdrop-blur-md p-5 rounded-3xl border shadow-lg transition-all duration-300 min-w-[120px]
                 ${isBadForm ? 'bg-red-50/90 border-red-200' : 'bg-white/90 border-gray-200'}
             `}>
                 <span className={`text-xs font-bold uppercase block mb-1 tracking-wider ${isBadForm ? 'text-red-700' : 'text-slate-500'}`}>
                    {metricLabel}
                 </span>
                 <div className="flex items-center gap-2">
                     <span className={`text-5xl font-bold tracking-tighter ${isBadForm ? 'text-red-600' : 'text-gray-900'}`}>
                         {displayMetric}°
                     </span>
                 </div>
             </div>
         </div>

         {/* Coach Insight */}
         {coachInsight && (
           <div className="absolute top-24 left-4 right-4 flex justify-center z-40 pointer-events-none">
             <div className="bg-white/95 backdrop-blur-md p-4 rounded-2xl shadow-xl border border-gray-200 pointer-events-auto max-w-lg flex items-start gap-4 animate-fade-in-down">
                <div className="p-2.5 bg-[#778873] rounded-xl text-white shrink-0 shadow-sm">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                </div>
                <div className="flex-1">
                    <p className="text-[#778873] font-bold text-xs uppercase tracking-wider mb-1">AI Coach Insight</p>
                    <p className="text-gray-800 text-sm leading-relaxed">
                        {coachInsight}
                    </p>
                </div>
                 <button 
                    onClick={() => setCoachInsight(null)}
                    className="text-slate-400 hover:text-gray-900"
                 >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                 </button>
             </div>
           </div>
         )}

         {!window.Pose && (
             <div className="absolute inset-0 flex items-center justify-center bg-white z-30">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#778873] mx-auto mb-4"></div>
                    <p className="text-gray-900 font-medium">Initializing Vision Engine...</p>
                </div>
             </div>
        )}
      </div>

      <div className="shrink-0 z-20 p-4 bg-white border-t border-gray-200">
          <div className="max-w-xl mx-auto flex flex-col md:flex-row gap-3">
               <Button 
                   fullWidth 
                   onClick={startAnalysisCountdown}
                   disabled={isAnalyzing || countdown !== null}
                   variant="outline"
                   icon={isAnalyzing ? <div className="animate-spin h-5 w-5 border-2 border-[#778873] rounded-full border-t-transparent"/> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>}
               >
                   {countdown !== null ? `Capturing in ${countdown}...` : (isAnalyzing ? "Analyzing..." : "Analyze Posture")}
               </Button>

               <Button 
                   fullWidth 
                   variant="primary" 
                   onClick={handleFinish}
               >
                   End Session
               </Button>
          </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Session } from '../types';
import { Button } from './Button';

interface ReportCardProps {
  session: Session;
  onClose: () => void;
}

export const ReportCard: React.FC<ReportCardProps> = ({ session, onClose }) => {
  const dateStr = session.timestamp.toLocaleDateString();
  const timeStr = session.timestamp.toLocaleTimeString();

  const handleDownloadPDF = () => {
    if (!window.jspdf) {
        console.error("jsPDF not loaded");
        return;
    }

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    // Header
    doc.setFontSize(20);
    doc.setTextColor(119, 136, 115); // Sage Color
    doc.text("Kinexa - Physical Therapy Session", 14, 22);

    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.text(`Date: ${dateStr} at ${timeStr}`, 14, 30);
    doc.text(`Patient ID: Local User`, 14, 35);

    // Table Data
    const tableData = Object.entries(session.exerciseStats || {})
      .filter(([_, val]) => (val as number) > 0)
      .map(([name, val]) => [
        name, 
        name === 'Plank' ? `${val} seconds` : `${val} reps`, 
        "Completed"
      ]);

    if (tableData.length === 0) {
        tableData.push(["No exercises performed", "-", "-"]);
    }

    // AutoTable
    doc.autoTable({
        startY: 45,
        head: [['Exercise Name', 'Result', 'Notes']],
        body: tableData,
        headStyles: { fillColor: [119, 136, 115] },
        styles: { font: "helvetica" }
    });

    // AI Insight
    const finalY = (doc as any).lastAutoTable.finalY || 60;

    doc.setFontSize(12);
    doc.setTextColor(0);
    doc.text("Clinical Notes", 14, finalY + 15);

    doc.setFontSize(10);
    doc.setTextColor(80);
    const splitText = doc.splitTextToSize(session.aiSummary, 180);
    doc.text(splitText, 14, finalY + 22);

    doc.save(`kinexa-report-${session.timestamp.getTime()}.pdf`);
  };

  return (
    <div className="min-h-screen bg-white flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden border border-gray-200">
        {/* Header */}
        <div className="bg-[#778873] p-8 text-white">
          <div className="flex justify-between items-center mb-2">
            <h2 className="text-2xl font-bold font-display tracking-wide">Session Report Card</h2>
            <div className="p-2 bg-white/10 rounded-lg">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
            </div>
          </div>
          <p className="opacity-90">{dateStr} • {timeStr}</p>
        </div>

        {/* Content */}
        <div className="p-8 space-y-8">

          {/* Detailed Exercise Grid */}
          <div>
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4">Exercises Performed</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {Object.entries(session.exerciseStats || {}).length > 0 ? (
                    Object.entries(session.exerciseStats)
                    .filter(([_, val]) => (val as number) > 0)
                    .map(([name, val]) => (
                        <div key={name} className="bg-white p-4 rounded-xl border border-gray-200 flex justify-between items-center shadow-sm">
                            <span className="font-bold text-gray-900">{name}</span>
                            <span className="text-[#778873] font-bold bg-green-50 px-3 py-1 rounded-lg">
                                {name === 'Plank' ? `${val}s` : `${val} reps`}
                            </span>
                        </div>
                    ))
                ) : (
                    <p className="text-slate-500 text-sm">No exercises recorded.</p>
                )}
            </div>
          </div>

          {/* AI Summary */}
          <div className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm ring-1 ring-[#778873]/5">
             <h3 className="text-[#778873] font-bold text-sm uppercase tracking-wider mb-3 flex items-center gap-2">
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>
                Clinical Observation
             </h3>
             <p className="text-gray-800 leading-relaxed italic text-lg">
                "{session.aiSummary}"
             </p>
          </div>

          <div className="flex gap-4">
             <div className="flex-1 bg-gray-50 p-3 rounded-xl border border-gray-100 text-center">
                <p className="text-xs text-slate-500 uppercase font-bold">Accuracy</p>
                <p className="text-xl font-bold text-gray-900">{session.accuracyScore}%</p>
             </div>
             <div className="flex-1 bg-gray-50 p-3 rounded-xl border border-gray-100 text-center">
                <p className="text-xs text-slate-500 uppercase font-bold">Total Time</p>
                <p className="text-xl font-bold text-gray-900">{Math.floor(session.durationSeconds / 60)}m {session.durationSeconds % 60}s</p>
             </div>
          </div>

          {/* Actions */}
          <div className="flex flex-col sm:flex-row gap-4 pt-4 border-t border-gray-100">
            <Button 
                onClick={handleDownloadPDF}
                variant="primary" 
                fullWidth
                icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>}
            >
                Download PDF Report
            </Button>
            <Button 
                onClick={onClose}
                variant="outline"
                fullWidth
            >
                Close & Save
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};
